window.EXPL={"세무사2016_53-41-1":{"f":"민사에 관하여 법률에 규정이 없으면 관습법에 의하고 관습법이 없으면 조리에 의한다.","w":"민법 제1조는 법률, 관습법, 조리의 순서로 적용한다고 정한다. 판례는 민법상 법원(法源)이 아니다.","c":"상","v":1},"세무사2016_53-41-2":{"f":"민법 제1조상의 법률이란 국회가 제정한 법률 외에 대통령이 발한 긴급 재정ㆍ경제명령도 포함하므로 이에 해당된다.","w":"긴급 재정ㆍ경제명령은 헌법상 법률과 같은 효력이 있어 민사에 관한 것이면 민법의 법원이 된다.","c":"상","v":1},"세무사2016_53-41-4":{"f":"대법원은 관습법과 사실인 관습을 구별한다.","w":"관습법은 법적 확신을 갖춘 법규범이라 법원이 직권으로 확정하고, 사실인 관습은 법률행위 해석의 표준이나 의사 보충 자료로 쓰이며 당사자가 주장ㆍ증명해야 한다. 대법원은 이 둘을 구별한다.","c":"상","v":1},"세무사2016_53-41-5":{"f":"관습법의 존재 여부는 원칙적으로 법원이 직권으로 확정하며 당사자가 증명할 필요가 없다.","w":"관습법은 법규범이므로 당사자의 주장ㆍ증명이 없어도 법원이 직권으로 확정한다.","c":"상","v":1},"세무사2017_54-42-1":{"f":"권리가 경합되는 경우에는 권리자는 그 중 어느 하나를 선택하여 행사할 수 있다.","w":"권리가 경합하면 권리자는 하나를 골라 행사할 수 있고, 먼저 성립한 권리부터 행사해야 하는 것은 아니다.","c":"상","v":1},"세무사2017_54-42-3":{"f":"일반채권이 서로 충돌하는 경우에는 성립의 선후와 관계없이 평등하게 취급된다.","w":"일반채권에는 채권자평등의 원칙이 적용되어 먼저 성립했다고 우선하지 않는다.","c":"상","v":1},"세무사2017_54-42-4":{"f":"소유권과 제한물권이 충돌하면 제한물권이 소유권에 우선한다.","w":"제한물권은 소유권의 권능 일부를 제한하는 물권이라 소유권과 충돌하면 제한물권이 앞선다.","c":"상","v":1},"세무사2017_54-42-5":{"f":"물권과 채권이 충돌하는 경우에는 원칙적으로 물권이 채권에 우선한다.","w":"물권은 채권보다 강한 효력이 있어 물권과 채권이 충돌하면 원칙적으로 물권이 우선한다.","c":"상","v":1},"세무사2017_54-45-4":{"f":"어떤 법률요건에 관한 규정을 이와 유사한 다른 것에 적용하는 민법의 해석방법을 유추해석이라고 한다.","w":"유사한 다른 사항에 규정을 적용하는 해석은 유추해석이다. 준용은 법률이 다른 규정을 필요한 수정을 하여 적용하라고 명시하는 입법기술이다.","c":"상","v":1},"세무사2021_58-41-2":{"f":"채무자의 소멸시효에 기한 항변권의 행사도 신의칙의 지배를 받는다.","w":"소멸시효 항변권의 행사도 신의칙에 반하거나 권리남용에 해당하면 허용되지 않는다.","c":"상","v":1},"세무사2021_58-41-3":{"f":"신의칙은 당사자의 주장이 없더라도 법원이 직권으로 판단할 수 있다.","w":"신의칙 위반과 권리남용은 법원의 직권조사사항이다.","c":"상","v":1},"세무사2021_58-41-4":{"f":"권리의 행사에 의하여 얻는 이익보다 상대방에게 발생할 손해가 현저히 크다는 사정만으로는 권리남용이 되지 않는다.","w":"권리남용이 되려면 권리 행사가 오직 상대방에게 고통이나 손해를 주려는 목적이어야 한다. 이익과 손해의 크기 차이만으로는 부족하다.","c":"상","v":1},"세무사2021_58-41-5":{"f":"채권자가 유효하게 성립한 계약에 따른 급부의 이행을 청구하는 때에 법원이 신의칙에 따라 급부의 일부를 감축하는 것은 원칙적으로 허용되지 않는다.","w":"유효한 계약의 내용을 신의칙으로 법원이 임의로 고쳐 급부를 줄일 수는 없다. 계약 구속력이 원칙이고 예외는 극히 제한된다.","c":"중","v":1},"세무사2022_59-41-2":{"f":"적법하게 체결ㆍ공포된 국제조약이 민사에 관한 것이면 민법의 법원이 될 수 있다.","w":"헌법에 의해 체결ㆍ공포된 조약은 국내법과 같은 효력이 있어 민사에 관한 것이면 민법의 법원이 된다.","c":"상","v":1},"세무사2022_59-41-3":{"f":"관습법이 그 적용시점에서 전체 법질서에 부합하지 않는다면 그 법적 규범으로서의 효력이 부정된다.","w":"관습법도 사회 변화로 현재의 전체 법질서에 반하게 되면 법적 규범으로서의 효력을 잃는다.","c":"상","v":1},"세무사2022_59-41-4":{"f":"당사자의 주장이 없더라도 법원이 직권으로 관습법의 존재를 확정할 수 있다.","w":"관습법은 법규범이라 당사자 주장 없이도 법원이 직권으로 확정한다.","c":"상","v":1},"세무사2022_59-41-5":{"f":"민사에 관한 대통령의 헌법상 긴급명령은 민법의 법원이 될 수 있다.","w":"긴급명령은 법률과 같은 효력이 있어 민사에 관한 것이면 민법의 법원이 된다.","c":"상","v":1},"세무사2023_60-41-5":{"f":"대법원 전원합의체 판결에서 설시된 추상적ㆍ일반적 법명제도 법원이 되지 않는다.","w":"판례는 우리 법제에서 법원(法源)이 아니다. 전원합의체 판결의 법명제도 마찬가지다.","c":"상","v":1},"세무사2023_60-42-3":{"f":"공중의 통행에 공용되는 도로 부지의 소유자는 그 도로를 점유ㆍ관리하는 지방자치단체를 상대로 도로의 철거를 청구할 수 없다.","w":"공중의 통행에 제공되어 지방자치단체가 관리하는 도로의 철거 청구는 권리남용에 해당해 허용되지 않는다는 것이 판례다.","c":"중","v":1},"세무사2023_60-77-2":{"f":"계약의 합의해지는 형성권의 행사가 아니라 당사자 사이의 계약이다.","w":"합의해지는 당사자 쌍방의 합의로 기존 계약을 소멸시키는 새로운 계약이다. 일방의 의사표시로 하는 해제·해지와 달라 형성권의 행사가 아니다.","c":"상","v":1},"세무사2024_61-42-5":{"f":"丙이 X의 상공에 송전선이 통과된다는 사실을 알고 X를 매수한 경우에도, 丙의 철거청구는 특별한 사정이 없는 한 신의칙에 반한다고 할 수 없다.","w":"송전선이 지나는 사실을 알고 매수했다는 사정만으로 철거청구가 신의칙에 반하는 것은 아니다. 권리남용은 엄격하게 인정된다.","c":"중","v":1},"세무사2025_62-61-3":{"f":"사회의 거듭된 관행으로 생성된 사회생활규범이 관습법으로 승인되었더라도, 그 후 사회 구성원들이 그러한 관행의 법적 구속력에 대하여 확신을 갖지 않게 되었다면 법적 규범으로서 효력을 잃는다.","w":"관습법은 법적 확신이 있어야 성립하고 유지된다. 확신이 사라지면 효력도 상실한다.","c":"상","v":1},"세무사2025_62-63-4":{"f":"계약의 무권대리인이 본인을 단독상속한 경우에 본인의 지위에서 자신이 한 무권대리행위의 추인을 거절하는 것은 특별한 사정이 없는 한 신의성실의 원칙에 반한다.","w":"자기가 한 무권대리행위의 책임을 지는 자가 상속으로 본인 지위를 얻어 추인을 거절하는 것은 모순된 행동이어서 신의칙에 반한다(대법원 판례).","c":"상","v":1},"세무사2026_63-41-4":{"f":"관습법이 제정법상 임의규정과 배치되는 경우에는 원칙적으로 임의규정이 우선한다.","w":"관습법은 성문법을 보충하는 효력만 있어서 제정법의 임의규정과 충돌하면 임의규정이 앞선다.","c":"중","v":1},"세무사2016_53-43-1":{"f":"미성년자가 법률행위를 함에 있어서 요구되는 법정대리인의 동의는 묵시적으로도 할 수 있다.","w":"법정대리인의 동의에는 방식 제한이 없어 명시적이든 묵시적이든 상관없다.","c":"상","v":1},"세무사2016_53-43-3":{"f":"혼인한 미성년자는 법정대리인의 동의가 없어도 단독으로 유효한 매매계약을 체결할 수 있다.","w":"미성년자가 혼인하면 성년으로 의제되어(제826조의2) 단독으로 완전한 법률행위를 할 수 있다.","c":"상","v":1},"세무사2016_53-43-4":{"f":"법정대리인으로부터 그 종류를 특정하여 허락을 얻은 영업에 관하여 미성년자는 성년자와 동일한 행위능력이 있다.","w":"영업허락은 영업의 종류를 특정하여 해야 하고(제8조 제1항), 포괄적 허락은 효력이 없다.","c":"상","v":1},"세무사2016_53-43-5":{"f":"미성년자의 법률행위에 법정대리인의 동의를 요한다는 민법규정은 강행규정이다.","w":"제한능력자 보호 규정은 강행규정이므로 당사자가 특약으로 배제할 수 없다.","c":"상","v":1},"세무사2016_53-47-2":{"f":"특정후견은 본인의 의사에 반하여 할 수 없다.","w":"특정후견은 본인의 의사에 반하여 할 수 없다(제14조의2 제2항).","c":"상","v":1},"세무사2016_53-47-3":{"f":"가정법원이 피성년후견인에 대하여 한정후견개시의 심판을 할 때에는 종전의 성년후견에 대한 종료심판을 하여야 한다.","w":"제14조의3 제2항에 따라 피성년후견인에 대해 한정후견개시 심판을 할 때는 종전의 성년후견 종료심판을 해야 한다.","c":"상","v":1},"세무사2016_53-47-4":{"f":"가정법원이 피한정후견인에 대하여 성년후견개시의 심판을 할 때에는 종전의 한정후견에 대한 종료심판을 하여야 한다.","w":"제14조의3 제1항에 따라 후견 유형을 바꿀 때는 종전 후견의 종료심판을 함께 해야 한다.","c":"상","v":1},"세무사2016_53-47-5":{"f":"가정법원이 한정후견개시의 심판을 할 때는 본인의 의사를 고려하여야 하고, 성년후견개시의 심판을 할 때도 마찬가지이다.","w":"성년후견과 한정후견 모두 개시심판 시 본인의 의사를 고려해야 한다(제9조 제2항, 제12조 제2항).","c":"상","v":1},"세무사2017_54-43-5":{"f":"상속개시 당시에 태아인 경우에도 그 후 출생하면 상속권이 인정된다.","w":"태아는 상속순위에 관하여는 이미 출생한 것으로 본다(제1000조 제3항).","c":"상","v":1},"세무사2021_58-43-5":{"f":"법정대리인이 미성년자에게 영업을 허락한 경우 법정대리인은 이를 취소할 수 있으나 선의의 제3자에게 대항할 수 없다.","w":"영업허락의 취소나 제한은 선의의 제3자에게 대항하지 못한다(제8조 제2항).","c":"상","v":1},"세무사2021_58-48-4":{"f":"피특정후견인의 행위능력은 제한되지 않는다.","w":"특정후견심판을 받아도 피특정후견인의 행위능력은 제한되지 않는다. 후원이 필요한 범위에서 대리권이나 동의권이 주어질 뿐이다.","c":"상","v":1},"세무사2022_59-43-1":{"f":"법인도 성년후견인이 될 수 있다.","w":"성년후견인은 자연인에 한하지 않고 법인도 될 수 있다(제930조 제3항).","c":"상","v":1},"세무사2022_59-43-2":{"f":"가정법원은 본인의 의사를 고려하여 성년후견개시의 심판을 하여야 한다.","w":"성년후견개시 심판을 할 때 가정법원은 본인의 의사를 고려해야 한다.","c":"상","v":1},"세무사2022_59-43-3":{"f":"가정법원은 취소할 수 없는 피성년후견인의 법률행위의 범위를 정한 후에도 본인의 청구가 있으면 그 범위를 변경할 수 있다.","w":"취소할 수 없는 법률행위의 범위는 본인, 후견인 등의 청구로 가정법원이 변경할 수 있다(제10조 제3항).","c":"상","v":1},"세무사2022_59-43-5":{"f":"가정법원은 피특정후견인에 대하여 특정후견의 종료 심판과 함께 한정후견개시의 심판을 하여야 한다.","w":"피특정후견인에 대해 한정후견이나 성년후견을 개시할 때도 종전의 특정후견 종료심판을 함께 해야 한다(제14조의3).","c":"상","v":1},"세무사2022_59-44-5":{"f":"인정사망은 사망의 추정력이 있을 뿐이므로 반대의 증거가 제출되면 그 효력이 소멸한다.","w":"인정사망은 사망을 추정하는 효력만 있어서 반증이 있으면 번복된다. 실종선고와 달리 취소 절차가 필요 없다.","c":"상","v":1},"세무사2022_59-45-2":{"f":"丙이 乙로부터 매매대금의 일부를 수령한 경우에는 丙은 甲이 제한능력자임을 이유로 매매계약을 취소할 수 없다.","w":"취소권자가 추인할 수 있는 후에 이행의 전부나 일부를 받으면 법정추인이 되어 취소권을 잃는다(제145조).","c":"중","v":1},"세무사2023_60-43-4":{"f":"丙이 매매계약 체결시 甲이 미성년자임을 알았더라도 乙에게 매매계약의 추인여부에 대한 확답을 촉구할 수 있다.","w":"상대방의 최고권은 상대방의 선의ㆍ악의를 묻지 않고 인정된다(제15조).","c":"상","v":1},"세무사2023_60-44-3":{"f":"피성년후견인이 속임수로써 법정대리인의 동의가 있는 것으로 믿게 하여 매매계약을 체결하였더라도 성년후견인은 계약을 취소할 수 있다.","w":"피성년후견인의 행위는 성년후견인의 동의가 있어도 취소할 수 있으므로 동의가 있는 것으로 믿게 했다는 사정은 취소권을 막지 못한다. 제17조 제2항은 동의를 갈음할 수 있는 제한능력자에게만 의미가 있다.","c":"중","v":1},"세무사2023_60-45-5":{"f":"실종선고를 받은 자도 권리능력을 상실하지 않는다.","w":"실종선고는 종래 주소지를 중심으로 한 법률관계에서 사망으로 보는 것일 뿐 권리능력 자체를 없애지 않는다.","c":"상","v":1},"세무사2024_61-43-1":{"f":"미성년자임을 이유로 하는 의사표시의 취소는 선의의 제3자에게도 대항할 수 있다.","w":"제한능력을 이유로 한 취소는 절대적 효력이 있어 선의의 제3자에게도 대항할 수 있다.","c":"상","v":1},"세무사2024_61-44-1":{"f":"불법행위로 인하여 태아가 사산된 경우, 태아는 불법행위로 인한 손해배상청구권을 취득하지 못한다.","w":"판례는 태아가 살아서 출생한 때에 비로소 권리를 취득한다고 본다(정지조건설). 사산되면 손해배상청구권이 생기지 않는다.","c":"상","v":1},"세무사2024_61-44-2":{"f":"의사능력의 유무는 구체적인 법률행위마다 개별적으로 판단한다.","w":"의사능력은 연령으로 획일적으로 정해지지 않고 법률행위의 내용과 관련해 개별적으로 판단한다. 행위능력만 획일적으로 판단한다.","c":"상","v":1},"세무사2024_61-44-4":{"f":"의사무능력자가 스스로 체결한 계약에 대해 의사무능력을 이유로 무효를 주장하는 것은 특별한 사정이 없는 한 신의칙에 반하지 않는다.","w":"의사무능력자의 법률행위는 당연히 무효이고, 그 무효를 주장하는 것이 신의칙 위반이 되지는 않는다.","c":"중","v":1},"세무사2024_61-44-5":{"f":"부재자가 실종선고를 받은 경우에도 그의 권리능력은 소멸하지 않는다.","w":"실종선고는 종래 주소를 중심으로 한 사법상 법률관계만 사망으로 의제하고, 생존 자체나 권리능력은 소멸시키지 않는다.","c":"상","v":1},"세무사2024_61-45-3":{"f":"가정법원은 정신적 제약으로 일시적 후원의 필요가 있는 경우에도 본인의 의사에 반하여 특정후견심판을 할 수 없다.","w":"특정후견은 본인의 의사에 반하여 할 수 없다(제14조의2 제2항).","c":"상","v":1},"세무사2025_62-44-1":{"f":"미성년자가 무이자로 돈을 빌리는 경우에도 법정대리인의 동의를 받아야 한다.","w":"금전을 빌리면 반환채무를 지게 되므로 권리만 얻거나 의무를 면하는 행위가 아니다. 무이자여도 동의가 필요하다.","c":"중","v":1},"세무사2025_62-44-2":{"f":"미성년자가 자신의 법률행위를 취소하기 위해서는 법정대리인의 동의를 얻을 필요가 없다.","w":"제한능력자 본인도 단독으로 취소할 수 있다(제140조).","c":"상","v":1},"세무사2025_62-44-4":{"f":"법원이 한정후견인의 동의를 받도록 한 법률행위를 피한정후견인이 단독으로 한 경우 그 법률행위는 취소할 수 있다.","w":"동의 없이 한 행위는 무효가 아니라 유효하게 성립하되 취소할 수 있는 행위다(제13조 제4항).","c":"상","v":1},"세무사2025_62-44-5":{"f":"계약체결 당시 일방이 제한능력자임을 알고 있었던 상대방은 자신의 의사표시를 철회할 수 없다.","w":"철회권은 제한능력자임을 몰랐던 선의의 상대방에게만 인정된다(제16조 제1항).","c":"상","v":1},"세무사2026_63-43-1":{"f":"태아는 법정대리인을 통하여 수증행위를 할 수 없다.","w":"판례는 태아가 살아서 출생한 때 권리능력을 취득한다고 보므로 태아 상태에서 대리인을 통한 증여 수령은 불가능하다.","c":"상","v":1},"세무사2026_63-43-2":{"f":"실종선고를 받은 자도 권리능력을 상실하지 않는다.","w":"실종선고는 종래 주소지 중심의 법률관계에서 사망으로 간주할 뿐이고 권리능력은 그대로다.","c":"상","v":1},"세무사2026_63-43-3":{"f":"의사능력의 유무는 구체적인 법률행위마다 개별적으로 판단한다.","w":"의사능력은 연령에 따라 획일적으로 정해지지 않고 해당 행위의 의미를 이해할 수 있는지에 따라 개별 판단한다.","c":"상","v":1},"세무사2026_63-43-5":{"f":"의사무능력자가 스스로 체결한 계약에 대해 의사무능력을 이유로 무효를 주장하는 것은 특별한 사정이 없는 한 신의칙에 반하지 않는다.","w":"의사무능력으로 인한 무효를 주장하는 것은 정당한 권리 행사로 신의칙 위반이 아니다.","c":"중","v":1},"세무사2026_63-44-5":{"f":"甲의 법정대리인이 계약을 추인하는 경우, 그 추인은 취소의 원인이 소멸하기 전에도 효력이 있다.","w":"취소의 원인이 소멸한 후라는 요건은 제한능력자 본인이 추인할 때만 적용된다. 법정대리인은 언제든 추인할 수 있다.","c":"상","v":1},"세무사2026_63-45-5":{"f":"가정법원은 본인의 복리상 필요한 경우에도 본인의 의사에 반하여 특정후견 개시의 심판을 할 수 없다.","w":"특정후견은 본인의 의사에 반하여 할 수 없다(제14조의2 제2항).","c":"상","v":1},"세무사2016_53-45-1":{"f":"법원에 의하여 선임된 재산관리인은 보수를 받을 수 있다.","w":"법원은 선임한 재산관리인에게 부재자의 재산으로 상당한 보수를 지급할 수 있다(제26조 제2항).","c":"상","v":1},"세무사2016_53-45-2":{"f":"부재자가 정한 재산관리인도 부재자의 생사가 분명하지 않은 때에는 법원의 명에 따라 재산의 관리 및 반환에 관한 담보를 제공하여야 한다.","w":"부재자 본인이 정한 관리인에게는 원칙적으로 법원이 개입하지 않으나, 생사가 분명하지 않으면 법원 선임 관리인에 관한 규정이 준용되어 담보제공을 명할 수 있다(제26조 제3항).","c":"중","v":1},"세무사2016_53-45-3":{"f":"법원은 재산관리인이 허가 없이 한 처분행위를 추인하기 위해서 사후에 이를 허가할 수 있다.","w":"판례는 법원의 허가를 사후 추인의 방법으로도 할 수 있다고 본다.","c":"상","v":1},"세무사2016_53-45-5":{"f":"재산관리인이 부재자의 재산매각처분에 대한 법원의 허가를 받았더라도, 통상의 경우 부재자와 무관한 제3자의 채무담보만을 위하여 부재자의 재산에 근저당권을 설정하는 것은 유효하다고 할 수 없다.","w":"법원의 허가를 받았어도 부재자와 상관없는 제3자의 채무를 담보하려고 부재자 재산에 근저당권을 설정하는 것은 재산 보존이라는 관리인의 직무 취지에 어긋난다.","c":"중","v":1},"세무사2016_53-46-3":{"f":"甲에 대한 실종선고에 의하여 甲은 실종기간이 만료한 때에 사망한 것으로 의제된다.","w":"사망으로 보는 시점은 실종된 날이 아니라 실종기간이 만료한 때다(제28조).","c":"상","v":1},"세무사2016_53-46-5":{"f":"乙이 2016. 3. 10. 甲 소유의 물건을 戊에게 매각하여 소유권을 넘겨준 후 甲의 실종선고가 취소되더라도, 乙과 戊가 모두 선의였다면 戊는 소유권을 그대로 보유한다.","w":"실종선고 후 그 취소 전에 선의로 한 행위의 효력에는 영향이 없다(제29조 제1항 단서). 계약이라면 당사자 쌍방이 선의여야 한다는 것이 통설이다. 현존이익을 반환할 문제가 아니다.","c":"중","v":1},"세무사2017_54-46-1":{"f":"실종선고를 받은 자는 실종기간이 만료한 때에 사망한 것으로 본다.","w":"실종선고는 사망을 추정하는 것이 아니라 사망으로 간주하는 효과가 있다.","c":"상","v":1},"세무사2017_54-46-2":{"f":"실종자를 사망한 것으로 보는 시기는 실종선고가 이루어진 때가 아니라 실종기간이 만료한 때이다.","w":"사망 간주 시점은 실종기간 만료 시이며 선고 시점이 아니다(제28조).","c":"상","v":1},"세무사2017_54-46-3":{"f":"실종선고의 효력은 사법상 법률관계에만 미치고, 공법상 법률관계에는 그 효력이 미치지 않는다.","w":"실종선고는 실종자의 종래 주소ㆍ거소를 중심으로 하는 사법상 법률관계에만 영향을 준다.","c":"상","v":1},"세무사2017_54-46-4":{"f":"이해관계 없는 후순위 상속인은 선순위 상속인이 있으면 실종선고를 청구할 수 없다.","w":"실종선고를 청구할 수 있는 이해관계인은 법률상 이해관계가 있는 사람이다. 선순위 상속인이 있으면 후순위 상속인은 포함되지 않는다.","c":"상","v":1},"세무사2021_58-44-1":{"f":"강가에서 낚시를 하고 있던 자의 생사가 5년간 분명하지 않은 경우에 이해관계인은 실종선고를 청구할 수 있다.","w":"일반 실종은 생사불명 상태가 5년 계속되어야 청구할 수 있다. 1년이면 되는 것은 전쟁, 선박, 항공기 사고 등 위난의 경우다.","c":"중","v":1},"세무사2021_58-44-3":{"f":"실종선고는 실종자의 종래 주소 또는 거소를 중심으로 하는 사법적 법률관계를 종료시킨다.","w":"실종선고의 효과는 사법상 법률관계에 한정되고 공법상 법률관계에는 미치지 않는다.","c":"상","v":1},"세무사2021_58-44-4":{"f":"실종자가 실종기간의 기산점 이후에 생존했음을 이유로 실종선고가 취소된 경우에도 다시 실종선고를 청구할 수 있다.","w":"실종선고가 취소되면 효력이 없어지고, 이후 요건을 갖추면 다시 청구할 수 있다.","c":"중","v":1},"세무사2021_58-44-5":{"f":"실종선고가 취소되면 실종선고를 직접원인으로 하여 재산을 취득한 자는 악의인 경우 받은 이익에 이자를 붙여 반환하고 손해가 있으면 배상하여야 한다.","w":"악의의 수익자는 받은 이익에 이자를 붙여 반환하고 손해가 있으면 배상해야 한다(제29조 제2항). 선의일 때만 현존이익을 반환한다.","c":"상","v":1},"세무사2021_58-46-2":{"f":"부재자의 부재 중에 재산관리인의 권한이 소멸한 때 법원은 이해관계인이나 검사의 청구에 의해 부재자의 재산관리에 필요한 처분을 명하여야 한다.","w":"이 경우 법원은 실종선고가 아니라 재산관리에 필요한 처분을 명한다(제22조 제1항 후단).","c":"상","v":1},"세무사2022_59-46-2":{"f":"실종선고를 받은 자는 실종기간이 만료한 때 사망한 것으로 본다.","w":"사망 간주 시점은 실종선고가 확정된 날이 아니라 실종기간이 만료한 때다.","c":"상","v":1},"세무사2023_60-46-2":{"f":"재산관리인이 부재자의 사망을 확인하였더라도 법원의 재산관리인 선임결정 취소 전에는 권한을 행사할 수 있다.","w":"법원이 선임한 재산관리인은 선임결정이 취소되거나 실종선고가 있기 전까지 권한을 행사한다.","c":"상","v":1},"세무사2024_61-46-4":{"f":"甲에 대한 실종선고가 확정되면 甲은 실종기간이 만료한 때에 사망한 것으로 간주된다.","w":"실종선고가 확정된 때가 아니라 실종기간이 만료한 때 사망한 것으로 본다. 원문에 적힌 날짜는 사안의 실종기간과 맞지 않는다.","c":"중","v":1},"세무사2025_62-42-2":{"f":"실종선고를 받은 자는 실종기간이 만료한 때에 사망한 것으로 본다.","w":"실종선고 확정일이 아니라 실종기간 만료 시에 사망한 것으로 본다.","c":"상","v":1},"세무사2025_62-42-3":{"f":"실종기간이 만료한 때와 다른 시기에 사망한 사실이 확인된 경우에는 실종선고를 취소할 수 있다.","w":"실종자가 생존해 있거나 실종기간 만료 시와 다른 시기에 사망한 사실이 증명되면 본인, 이해관계인, 검사의 청구로 실종선고를 취소한다(제29조 제1항).","c":"상","v":1},"세무사2025_62-42-4":{"f":"실종선고가 취소되면 실종선고를 직접원인으로 하여 재산을 취득한 자가 선의이면 현존 이익의 한도에서 반환하여야 한다.","w":"선의라고 해서 반환의무가 없지는 않다. 선의는 현존이익만, 악의는 받은 이익 전부와 이자 및 손해를 반환한다(제29조 제2항).","c":"상","v":1},"세무사2025_62-42-5":{"f":"순위가 다른 상속인이 여러 명인 경우에 후순위 상속인은 실종선고를 청구할 수 없다.","w":"선순위 상속인이 있으면 후순위 상속인은 법률상 이해관계인이 아니다.","c":"상","v":1},"세무사2025_62-46-1":{"f":"부재자로부터 재산처분권까지 위임받은 재산관리인이 그 재산을 처분하는 경우에는 특별한 사정이 없는 한 법원의 허가가 필요하지 않다.","w":"부재자가 정한 재산관리인이 처분권까지 위임받았다면 법원 허가 없이 처분할 수 있다. 법원이 선임했거나 개임된 뒤에는 허가가 필요하다.","c":"중","v":1},"세무사2026_63-46-5":{"f":"동일인에 대하여 실종선고가 확정된 후 그 실종선고가 취소됨이 없이 다시 실종선고가 내려진 경우, 먼저 확정된 실종선고에 따라 상속관계를 판단해야 한다.","w":"취소 없이 중복해서 내려진 실종선고는 효력이 없고 먼저 확정된 선고가 기준이 된다.","c":"중","v":1},"세무사2016_53-49-2":{"f":"법인설립등기는 주무관청의 설립허가가 있은 때로부터 3주 내에 주된 사무소소재지에서 하여야 한다.","w":"설립등기는 설립허가가 있은 날로부터 3주 내에 주된 사무소 소재지에서 한다(제49조 제1항).","c":"상","v":1},"세무사2016_53-49-3":{"f":"유언으로 재단법인을 설립하는 경우에는 유증에 관한 규정이 준용된다.","w":"생전처분으로 설립하면 증여 규정을, 유언으로 설립하면 유증 규정을 준용한다(제47조).","c":"상","v":1},"세무사2016_53-49-4":{"f":"법인이 설립허가의 조건에 위반한 경우 주무관청은 그 설립허가를 취소할 수 있다.","w":"법인이 설립허가 조건을 위반하면 주무관청은 허가를 취소할 수 있다(제38조).","c":"상","v":1},"세무사2016_53-49-5":{"f":"사단법인의 설립행위는 요식행위이다.","w":"사단법인 설립행위는 정관을 서면으로 작성하고 기명날인하는 요식행위다.","c":"상","v":1},"세무사2016_53-51-4":{"f":"대표자는 대리인에게 비법인사단의 제반 업무처리를 포괄적으로 위임할 수 없다.","w":"대표자는 특정한 사항을 개별적으로 위임할 수 있을 뿐 업무 전반을 포괄적으로 위임할 수 없다.","c":"상","v":1},"세무사2016_53-52-5":{"f":"각 사원은 평등한 결의권을 가지며, 정관에서 이를 달리 정할 수 있다.","w":"각 사원의 결의권은 평등하지만(제73조 제1항) 정관에 다른 규정이 있으면 이 규정은 적용되지 않는다(같은 조 제3항).","c":"상","v":1},"세무사2016_53-54-5":{"f":"이사의 결원으로 손해가 생길 염려가 있는 경우, 법원은 임시이사를 선임하여야 한다.","w":"이사 결원으로 손해가 생길 염려가 있으면 법원이 이해관계인이나 검사의 청구로 임시이사를 선임한다(제63조). 특별대리인은 법인과 이사의 이익이 상반하는 사항에 선임한다(제64조).","c":"상","v":1},"세무사2016_53-55-3":{"f":"대표자의 행위가 직무에 관한 행위에 해당하지 아니함을 피해자 자신이 중대한 과실로 알지 못한 경우에는 피해자는 법인에게 손해배상책임을 물을 수 없다.","w":"외형상 직무행위로 보여도 피해자가 직무 아님을 알았거나 중대한 과실로 몰랐다면 법인은 책임이 없다.","c":"상","v":1},"세무사2017_54-48-1":{"f":"사단법인에 관한 민법 규정 중 법인격을 전제로 한 규정을 제외하고는 법인 아닌 사단에도 유추 적용된다.","w":"설립허가, 등기처럼 법인격을 전제로 한 규정은 비법인사단에 유추할 수 없다.","c":"상","v":1},"세무사2017_54-48-2":{"f":"사원이 없게 되면 법인 아닌 사단도 청산절차를 거쳐야 소멸한다.","w":"비법인사단도 해산 후 청산절차를 거치며, 청산 목적 범위에서는 존속한다.","c":"중","v":1},"세무사2017_54-48-4":{"f":"법인 아닌 사단의 구성원 일부가 집단적으로 사단을 탈퇴하였더라도 기존의 법인 아닌 사단이 두 개의 독립한 사단으로 분열되었다고 볼 수 없다.","w":"비법인사단은 분열이 인정되지 않는다. 일부 탈퇴는 탈퇴일 뿐이고 기존 사단은 잔존 구성원으로 존속한다.","c":"상","v":1},"세무사2017_54-48-5":{"f":"종중(宗中) 재산의 관리 및 처분에 관하여 종중규약에서 규정하고 있지 않다면, 특별한 사정이 없는 한, 종중 총회의 결의에 의해 종중재산을 처분하여야 한다.","w":"종중재산은 구성원의 총유라서 규약이 없으면 총회 결의를 거쳐 처분한다. 대표가 단독으로 처분할 수 없다.","c":"상","v":1},"세무사2017_54-49-4":{"f":"이사가 수인인 경우에는 정관에 다른 규정이 없으면 법인의 사무집행은 이사의 과반수로 결정한다.","w":"이사가 여럿이면 정관에 다른 규정이 없을 때 사무집행은 이사 과반수로 정한다(제58조 제2항).","c":"상","v":1},"세무사2017_54-51-2":{"f":"법인의 정관변경은 사원총회의 전속적 권한에 속하므로, 이사회의 결의만으로 정관을 변경할 수 없다.","w":"사단법인의 정관변경은 사원총회의 권한이다(제42조 제1항).","c":"상","v":1},"세무사2017_54-54-1":{"f":"파산에 의하여 법인이 해산하는 경우에는 파산선고 당시의 이사가 청산인이 되지 않는다.","w":"이사가 청산인이 되는 것은 파산 외의 사유로 해산한 경우다(제82조). 파산으로 해산하면 파산절차에서 파산관재인이 재산을 정리한다.","c":"상","v":1},"세무사2017_54-54-2":{"f":"법인의 해산 및 청산에 관한 사무에 대해서는 법원이 이를 감독한다.","w":"해산과 청산은 주무관청이 아니라 법원이 검사ㆍ감독한다(제95조).","c":"상","v":1},"세무사2017_54-54-3":{"f":"청산인이 알고 있는 법인의 채권자는 채권신고 기간 내에 채권신고를 하지 않더라도 청산에서 제외할 수 없다.","w":"알고 있는 채권자는 신고 여부와 관계없이 청산에서 제외하지 못한다(제89조).","c":"상","v":1},"세무사2017_54-54-4":{"f":"청산인은 채권신고기간 내에는 채권자에게 변제하지 못하지만, 그 기간 중에 이행기가 도달한 채권을 변제하지 않으면 법인은 지연손해배상의무를 부담한다.","w":"채권신고기간 중에 변제하지 못하더라도 법인은 지연손해배상 책임을 면하지 못한다(제90조).","c":"상","v":1},"세무사2017_54-56-1":{"f":"재단법인은 감사를 둘 수 있으나 반드시 두어야 하는 것은 아니다.","w":"감사는 필수기관이 아니라 정관이나 총회의 결의로 둘 수 있는 임의기관이다(제66조).","c":"상","v":1},"세무사2017_54-56-3":{"f":"","w":"재단법인에는 사원이 없어 사원총회도 없다. 매년 1회 이상 통상총회를 소집할 의무는 사단법인의 이사에게 있다(제69조). 민법상 법인에는 대표이사라는 기관도 없다.","c":"상","v":1},"세무사2017_54-56-4":{"f":"재단법인의 존립시기와 해산사유는 정관에 반드시 기재하지 않아도 되는 사항이다.","w":"재단법인의 필수 기재사항은 목적, 명칭, 사무소, 자산, 이사 임면에 관한 규정이다. 존립시기와 해산사유는 정해진 경우에만 적는다(제43조, 제40조).","c":"상","v":1},"세무사2017_54-56-5":{"f":"유언으로 재단법인을 설립하는 행위는 유언의 방식을 따라야 하는 요식행위이다.","w":"유언은 법이 정한 방식을 따라야 하는 요식행위이므로 유언에 의한 설립도 마찬가지다.","c":"상","v":1},"세무사2021_58-42-3":{"f":"생전처분으로 재단법인을 설립하는 때에는 증여에 관한 규정을 준용한다.","w":"생전처분이면 증여 규정을, 유언이면 유증 규정을 준용한다(제47조).","c":"상","v":1},"세무사2021_58-45-4":{"f":"청산인이 알고 있는 채권자에 대해 각각 그 채권신고를 최고하였으나 채권신고가 없는 경우에도 청산인은 알고 있는 채권자를 청산에서 제외할 수 없다.","w":"알고 있는 채권자는 신고하지 않아도 청산에서 제외하지 못한다(제89조).","c":"상","v":1},"세무사2021_58-50-5":{"f":"재단법인의 목적을 달성할 수 없는 때 이사는 주무관청의 허가를 얻어 그 목적 기타 정관의 규정을 변경할 수 있다.","w":"목적 달성이 불가능한 재단법인이 설립취지를 참작해 정관을 변경하려면 주무관청의 허가가 필요하다(제46조).","c":"상","v":1},"세무사2021_58-51-2":{"f":"법인의 목적달성이 불능한 경우에는 설립허가의 취소 없이도 법인은 해산한다.","w":"목적달성의 불능은 법인의 법정 해산사유다(제77조 제1항). 설립허가 취소는 별개의 해산 사유다.","c":"상","v":1},"세무사2021_58-51-3":{"f":"청산종결등기가 마쳐졌더라도 청산사무가 종료되지 않았다면 청산법인은 소멸하지 않는다.","w":"청산종결등기와 별개로 청산사무가 실제로 끝나지 않은 범위에서는 청산법인이 존속한다.","c":"상","v":1},"세무사2021_58-51-4":{"f":"청산 중에 법인의 채무초과상태가 분명하게 되어 청산인이 파산선고를 신청하더라도, 청산인의 임무는 파산관재인에게 그 사무를 인계함으로써 종료된다.","w":"청산인은 채무초과가 분명하면 지체 없이 파산선고를 신청해야 하고(제93조 제1항), 그 임무는 파산관재인에게 사무를 인계한 때 끝난다(같은 조 제2항).","c":"상","v":1},"세무사2021_58-51-5":{"f":"정관으로 이사 전원의 의결에 의하여 잔여재산을 처분하도록 하였으나 이를 등기하지 않은 경우, 그 정관을 위반한 잔여재산처분은 상대방이 이에 대해 선의라도 특별한 사정이 없는 한 무효이다.","w":"청산절차에 관한 민법 규정은 강행규정이고, 정관이 정한 잔여재산 처분 절차를 어긴 처분은 청산법인의 목적범위를 벗어난 행위라 상대방이 선의여도 무효라는 것이 판례다(제80조, 제81조). 대표권 제한의 대항요건(제60조)으로 다룰 문제가 아니다.","c":"중","v":1},"세무사2021_58-52-1":{"f":"사원총회의 결의로 사단법인을 해산할 수 없도록 한 정관은 무효이다.","w":"사단법인은 총회의 결의로 해산할 수 있고(제77조 제2항), 총회의 해산결의 권한을 빼앗는 정관 규정은 효력이 없다.","c":"중","v":1},"세무사2021_58-52-2":{"f":"사원이 대리인에 의하여 사원총회의 결의권을 행사하는 경우에도 출석한 것으로 본다.","w":"서면이나 대리인으로 결의권을 행사하는 사원은 출석한 것으로 본다(제75조 제2항).","c":"상","v":1},"세무사2021_58-52-3":{"f":"사단법인의 이사는 매년 1회 이상 통상총회를 소집하여야 한다.","w":"통상총회는 매년 1회 이상 소집한다(제69조).","c":"상","v":1},"세무사2021_58-52-4":{"f":"사단법인과 어느 사원과의 관계사항을 의결하는 경우에는 그 사원에게 사원총회에서의 결의권이 없다.","w":"법인과 이해가 충돌하는 사항에서는 해당 사원의 결의권이 배제된다(제74조).","c":"상","v":1},"세무사2021_58-56-3":{"f":"甲의 불법행위가 외형상 대표기관의 직무행위라고 볼 수 있더라도, 乙이 그 행위가 직무에 관한 행위가 아님을 안 경우에는 A의 불법행위는 인정되지 않는다.","w":"거래 상대방이 직무 행위가 아님을 알았거나 중대한 과실로 몰랐다면 법인의 불법행위책임이 성립하지 않는다.","c":"상","v":1},"세무사2021_58-60-4":{"f":"재단법인과 이사의 이익이 상반하는 사항에 대해서는 특별대리인이 선임되기 전까지 그 이사에게 대표권이 없다.","w":"이해가 상반되는 사항에서는 이사에게 대표권이 없고 법원이 선임한 특별대리인이 법인을 대표한다(제64조).","c":"상","v":1},"세무사2022_59-48-5":{"f":"교회는 비법인사단에 해당하지만 합병 및 분열이 인정되지 않는다.","w":"판례는 교회의 분열을 인정하지 않는다. 소속 교인이 이탈해도 기존 교회가 존속한다.","c":"상","v":1},"세무사2022_59-49-1":{"f":"A법인의 설립을 위하여 작성한 정관의 법적 성질은 자치법규이다.","w":"사단법인 정관은 계약이 아니라 사원을 구속하는 자치법규다.","c":"상","v":1},"세무사2022_59-49-4":{"f":"A법인은 특별한 사정이 없는 한, 총사원 4분의 3에 해당하는 9인 이상의 동의를 얻으면 해산을 결의할 수 있다.","w":"사단법인의 해산 결의는 정관에 다른 규정이 없으면 총사원 4분의 3 이상의 동의가 있어야 한다(제78조). 2/3로는 부족하다.","c":"중","v":1},"세무사2022_59-49-5":{"f":"A법인은 정관의 작성 이외에 재산의 출연을 그 설립요건으로 하지 않는다.","w":"재산 출연이 설립요건인 것은 재단법인이고, 사단법인은 정관 작성과 설립허가, 설립등기가 요건이다.","c":"상","v":1},"세무사2022_59-51-5":{"f":"총회에서의 결의가 유효하기 위해서는 원칙적으로 총회의 소집일 1주일 전까지 총회 소집 통지가 발송되어야 한다.","w":"총회 소집은 1주간 전에 목적사항을 기재한 통지를 발송하는 방식으로 하며 사원 전원에게 도달할 필요는 없다(제71조).","c":"중","v":1},"세무사2022_59-52-1":{"f":"사단법인은 사원이 없게 된 경우에 해산한다.","w":"사원이 1인만 남아도 사단법인은 해산하지 않고, 사원이 없게 되면 해산한다(제77조 제2항).","c":"상","v":1},"세무사2022_59-53-2":{"f":"법인에는 이사를 반드시 두어야 하지만 감사는 임의기관이다.","w":"이사는 필수기관이고 감사는 정관이나 총회의 결의로 둘 수 있는 임의기관이다(제57조, 제66조).","c":"상","v":1},"세무사2022_59-54-4":{"f":"감사의 행위에 대해서는 민법 제35조에 의한 법인의 불법행위책임이 성립하지 않는다.","w":"감사는 법인의 대표기관이 아니라 감독기관이어서 감사의 행위로 제35조 책임이 생기지 않는다.","c":"상","v":1},"세무사2023_60-47-1":{"f":"법인의 존립시기나 해산사유는 정관의 임의적 기재사항이다.","w":"존립시기와 해산사유는 정한 경우에만 적는 사항이며 필요적 기재사항이 아니다(제40조).","c":"상","v":1},"세무사2023_60-47-2":{"f":"설립자가 그 명칭을 정하지 않고 사망한 때에는 이해관계인 또는 검사의 청구에 의해 법원이 이를 정할 수 있다.","w":"법원이 정해 줄 수 있는 것은 명칭, 사무소, 이사 임면 방법이다. 목적과 자산은 설립자가 정해야 한다(제44조).","c":"상","v":1},"세무사2023_60-47-3":{"f":"설립자의 생전처분으로 재단법인에 출연된 물건에 하자가 있는 경우, 설립자는 그 하자를 몰랐다면 담보책임을 지지 않는다.","w":"생전처분에는 증여 규정이 준용되어 증여자는 하자를 알고 알리지 않은 경우에만 담보책임을 진다(제559조).","c":"중","v":1},"세무사2023_60-47-4":{"f":"설립자가 생전처분으로 부동산을 출연하여 재단법인을 설립하는 경우, 출연자와 법인과의 관계에서 출연부동산의 소유권은 법인이 성립한 때 귀속되며 이전등기가 필요하지 않다.","w":"출연자와 법인 사이에서는 법인 성립 시에 귀속되고, 제3자에 대한 관계에서만 등기를 해야 한다(제48조, 판례).","c":"상","v":1},"세무사2023_60-48-2":{"f":"학교법인 대표자의 직무상 차금(借金)행위가 불법행위가 되는 경우, 법인은 민법 제35조의 법인 불법행위 책임을 진다.","w":"대표자의 직무행위로 인한 책임은 사용자책임(제756조)이 아니라 제35조에 따른 법인 자체의 불법행위책임이다.","c":"상","v":1},"세무사2023_60-48-3":{"f":"법인의 불법행위책임이 성립하는 경우, 피해자는 직접 대표자에 대해서도 손해배상을 청구할 수 있다.","w":"법인이 책임을 져도 대표자 개인의 불법행위책임은 사라지지 않아 피해자는 둘 모두에게 청구할 수 있다(제35조 제1항).","c":"상","v":1},"세무사2023_60-48-4":{"f":"대표자의 행위가 직무에 관한 행위에 해당하지 않음을 피해자가 알고 있었다면 외형상 직무행위로 보이더라도 법인은 손해배상책임을 지지 않는다.","w":"피해자가 직무행위가 아님을 알았거나 중대한 과실로 몰랐다면 법인에 책임을 물을 수 없다.","c":"상","v":1},"세무사2023_60-48-5":{"f":"법인의 실질적 운영자로서 법인 사무를 집행함에도 대표자로 등기되어 있지 않은 자도 민법 제35조에서 정한 대표자로 볼 수 있다.","w":"등기 여부와 관계없이 실질적으로 법인을 운영하며 사무를 집행하는 사람은 제35조의 대표자에 포함된다.","c":"상","v":1},"세무사2023_60-49-1":{"f":"신임 이사에 대한 변경등기 전에 그 이사가 한 직무행위는 법인에 대하여 효력이 있다.","w":"이사 변경등기가 없으면 제3자에게 대항하지 못할 뿐이고, 신임 이사가 한 직무행위 자체는 법인에 효력이 미친다.","c":"중","v":1},"세무사2023_60-49-2":{"f":"이사의 대표권 제한은 정관에 규정하였더라도 등기하지 않으면 악의의 제3자에 대하여 대항할 수 없다.","w":"대표권 제한은 정관에 기재하고 등기해야 제3자에게 대항할 수 있다(제41조, 제60조).","c":"상","v":1},"세무사2023_60-49-4":{"f":"이사가 수인인 경우에 정관에 다른 규정이 없으면 법인의 내부적 사무집행은 이사 과반수로 결정한다.","w":"이사가 여럿이면 사무집행은 이사 과반수로 결정한다(제58조 제2항). 각자 단독으로 결정하는 것은 대표 방식이다.","c":"상","v":1},"세무사2023_60-49-5":{"f":"법인과 이사의 이익이 상반되는 사항에 대한 특별대리인은 법원에 의해 선임된다.","w":"이해상반 사항에서는 이해관계인이나 검사의 청구로 법원이 특별대리인을 선임한다(제64조).","c":"상","v":1},"세무사2016_53-56-3":{"f":"법정과실의 귀속에 관한 민법규정은 임의규정이다.","w":"과실의 귀속을 정한 제102조는 당사자가 특약으로 달리 정할 수 있는 임의규정이다.","c":"상","v":1},"세무사2016_53-57-5":{"f":"주물과 종물의 관계에 관한 민법상 법리는 물건 상호간뿐 아니라 권리 상호간에도 유추적용된다.","w":"판례는 건물과 대지이용권 같은 권리 상호간에도 주물ㆍ종물 법리를 유추적용한다.","c":"상","v":1},"세무사2016_53-58-3":{"f":"유체 및 유골은 제사주재자에게 소유권이 귀속되지만 제사주재자는 이를 포기할 수 없다.","w":"유골은 매장ㆍ관리ㆍ제사를 위한 특수한 소유권의 대상이고 제사주재자에게 승계되지만, 이를 임의로 포기하거나 처분할 수는 없다.","c":"중","v":1},"세무사2017_54-52-1":{"f":"무기명채권은 물건이 아니므로 동산에 해당하지 않는다.","w":"동산은 부동산 이외의 물건이고(제99조 제2항), 물건은 유체물과 관리할 수 있는 자연력이다(제98조). 무기명채권은 물건이 아닌 채권이며, 현행 민법에는 이를 동산으로 보는 규정이 없고 증서 교부로 양도하는 증권적 채권으로 따로 정한다(제523조).","c":"상","v":1},"세무사2021_58-47-3":{"f":"명인방법을 갖춘 수목은 독립하여 거래의 객체가 될 수 있다.","w":"명인방법을 갖춘 수목은 토지와 별개로 소유권 양도 등 거래의 대상이 된다.","c":"상","v":1},"세무사2021_58-49-3":{"f":"주식배당금은 법정과실이 아니다.","w":"법정과실은 물건의 사용대가로 받는 금전 기타 물건이다. 주식배당금은 주주권에서 나오는 이익이어서 민법상 법정과실에 해당하지 않는다.","c":"중","v":1},"세무사2022_59-55-3":{"f":"1필의 토지의 일부에 대해서는 이를 분할하지 않아도 용익물권을 설정할 수 있다.","w":"지상권, 지역권, 전세권 같은 용익물권은 1필 토지의 일부에도 설정할 수 있다. 분필이 필요한 것은 소유권이나 저당권이다.","c":"상","v":1},"세무사2022_59-56-1":{"f":"종물만을 별도로 처분하기로 하는 당사자 사이의 특약은 효력이 있다.","w":"제100조 제2항은 임의규정이어서 주물과 종물을 따로 처분하는 특약은 유효하다.","c":"상","v":1},"세무사2022_59-56-2":{"f":"권리 상호간에도 주물과 종물의 관계에 관한 법리가 유추적용될 수 있다.","w":"판례는 권리 상호간에도 주물ㆍ종물 법리를 유추적용한다.","c":"상","v":1},"세무사2022_59-56-4":{"f":"종물은 주물의 처분에 따른다고 하는 경우, 그 처분에 채권적 처분도 포함된다.","w":"제100조 제2항의 처분에는 물권적 처분뿐 아니라 매매 같은 채권적 처분도 포함된다.","c":"상","v":1},"세무사2022_59-56-5":{"f":"주물과 종물은 법률적 운명을 같이 하지만 각각 독립한 물건이다.","w":"종물은 주물과 따로 존재하는 독립된 물건이고, 처분만 주물을 따른다.","c":"상","v":1},"세무사2023_60-53-3":{"f":"토지의 정착물은 토지의 일부이지만 건물과 같이 토지와 별개의 부동산이 되는 것도 있다.","w":"토지의 정착물 중 건물은 토지와 독립한 별개의 부동산이다. 명인방법을 갖춘 수목도 독립한 거래 객체가 된다.","c":"상","v":1},"세무사2023_60-54-1":{"f":"민법상 주물의 소유자와 종물의 소유자는 동일인이어야 한다.","w":"제100조의 종물 관계는 주물과 종물의 소유자가 같아야 성립한다.","c":"상","v":1},"세무사2023_60-54-3":{"f":"물건의 사용대가로 받은 물건은 법정과실이다.","w":"천연과실은 물건의 용법에 따라 수취하는 산출물이고, 사용대가로 받는 금전 기타 물건은 법정과실이다(제101조).","c":"상","v":1},"세무사2023_60-54-4":{"f":"법정과실은 수취할 권리의 존속기간일수의 비율로 취득한다.","w":"일수 비율로 취득하는 것은 법정과실이다. 천연과실은 원물에서 분리하는 때 수취할 권리자에게 귀속된다(제102조).","c":"상","v":1},"세무사2023_60-54-5":{"f":"민법상 법정과실의 수취에 관한 규정은 임의규정이다.","w":"법정과실의 수취는 당사자가 특약으로 달리 정할 수 있는 임의규정이다.","c":"상","v":1},"세무사2024_61-53-5":{"f":"원본채권이 양도된 경우, 이미 변제기에 도달한 이자채권은 별도의 의사표시가 없으면 당연히 양도되지는 않는다.","w":"이미 변제기에 도달한 지분적 이자채권은 원본채권과 분리하여 양도할 수 있는 독립한 채권이어서 원본 양도에 당연히 따르지 않는다.","c":"상","v":1},"세무사2024_61-54-4":{"f":"1필의 토지의 일부에 관해 공간정보의 구축 및 관리 등에 관한 법률에 의한 분필절차를 거치지 않았다면 등기부상 분필등기가 실행되었더라도 분필의 효과가 생기지 않는다.","w":"토지의 개수와 경계는 지적공부상의 분할 절차를 거쳐야 정해지고, 등기부만으로는 분필되지 않는다.","c":"중","v":1},"세무사2025_62-69-1":{"f":"종물은 주물로부터 독립한 물건이면 되고 동산이어야 하는 것은 아니다.","w":"부동산도 종물이 될 수 있다. 독립한 건물이 주된 건물의 종물이 되는 것이 그 예다.","c":"상","v":1},"세무사2025_62-69-2":{"f":"주물, 종물의 이론은 물건 상호간뿐 아니라 권리 상호간에도 유추적용된다.","w":"판례는 권리 상호간에도 주물ㆍ종물 이론을 유추적용한다.","c":"상","v":1},"세무사2025_62-69-3":{"f":"주물의 소유자의 상용에 제공되고 있더라도 주물 그 자체의 효용과 직접 관계가 없는 물건은 종물이 아니다.","w":"종물은 주물 자체의 경제적 효용에 계속 이바지해야 한다. 소유자가 쓰고 있다는 사정만으로는 종물이 되지 않는다.","c":"상","v":1},"세무사2025_62-69-5":{"f":"주물에 설정된 저당권의 효력은 다른 정함이 없으면 종물에도 미친다.","w":"제358조에 따라 저당권의 효력은 저당 부동산에 부합된 물건과 종물에 미친다.","c":"상","v":1},"세무사2026_63-52-1":{"f":"온천수는 관습법상 물권의 객체가 아니다.","w":"판례는 온천에 관한 권리를 관습법상 물권으로 인정하지 않으며 온천수는 토지의 구성부분이다.","c":"상","v":1},"세무사2026_63-53-1":{"f":"주물의 효용을 일시적으로 돕는 것은 종물이 될 수 없다.","w":"종물은 주물의 경제적 효용에 계속적으로 이바지하는 관계에 있어야 한다.","c":"상","v":1},"세무사2026_63-53-3":{"f":"건물 내에 설치된 수세식 화장실의 정화조는 건물의 구성부분이다.","w":"정화조는 건물과 따로 쓸 수 없는 건물의 구성부분이어서 종물이 아니다.","c":"중","v":1},"세무사2026_63-53-4":{"f":"‘종물은 주물의 처분에 따른다’는 법리는 압류와 같은 공법상 처분에도 적용될 수 있다.","w":"판례는 제100조 제2항 법리가 압류 같은 공법상의 처분에도 적용된다고 본다.","c":"상","v":1},"세무사2026_63-53-5":{"f":"주물을 처분할 때 특약으로 종물을 처분대상에서 제외할 수 있다.","w":"제100조 제2항은 임의규정이므로 특약으로 종물을 제외할 수 있다.","c":"상","v":1},"세무사2016_53-60-3":{"f":"유언은 상대방 없는 단독행위에 해당한다.","w":"유언은 상대방 없이 유언자 혼자 하는 단독행위다.","c":"상","v":1},"세무사2016_53-61-1":{"f":"불공정한 법률행위의 성립요건인 궁박, 경솔, 무경험은 모두 구비되어야 하는 요건이 아니며, 그 중 일부만 갖추어도 충분하다.","w":"궁박, 경솔, 무경험은 그 중 하나만 갖추어도 충분하다.","c":"상","v":1},"세무사2016_53-61-2":{"f":"피해 당사자가 궁박, 경솔, 무경험의 상태에 있었더라도, 상대방에게 그와 같은 피해 당사자측의 사정을 알면서 이를 이용하려는 의사가 없었다면 불공정한 법률행위는 성립하지 않는다.","w":"폭리자에게 피해자의 사정을 알고 이용하려는 의사가 있어야 불공정한 법률행위가 성립한다.","c":"상","v":1},"세무사2016_53-61-3":{"f":"불공정한 법률행위에 해당하는지는 그 이행기가 아니라 법률행위성립 당시를 기준으로 판단하여야 한다.","w":"불공정 여부는 법률행위가 이루어진 때를 기준으로 판단한다.","c":"상","v":1},"세무사2016_53-61-5":{"f":"불공정한 법률행위에 해당하여 무효인 경우에는 당사자의 추인에 의하여도 그 법률행위는 유효로 될 수 없다.","w":"불공정한 법률행위는 절대적 무효여서 추인해도 유효가 되지 않는다.","c":"상","v":1},"세무사2016_53-62-5":{"f":"법률행위의 목적이 사회적 타당성을 결여하였다면 개별적인 강행법규에 위반하지 않았더라도 그 법률행위는 무효이다.","w":"선량한 풍속 기타 사회질서에 반하는 법률행위는 제103조에 따라 무효다. 개별 강행법규 위반 여부와 무관하다.","c":"상","v":1},"세무사2016_53-63-2":{"f":"반사회적 행위에 의하여 조성된 비자금을 소극적으로 은닉하기 위한 임치계약은 사회질서에 반하는 법률행위로 볼 수 없다.","w":"비자금을 소극적으로 숨겨 두기 위한 임치는 반사회질서의 법률행위가 아니라는 것이 판례다.","c":"상","v":1},"세무사2017_54-57-1":{"f":"법률행위가 성립하기 위해서는 법률행위 당시에 그 목적이 확정되어 있거나 장차 확정될 수 있어야 한다.","w":"목적이 성립 당시 확정되어 있을 필요는 없고 이행 단계에서 확정할 수 있으면 된다.","c":"상","v":1},"세무사2017_54-57-2":{"f":"법률행위는 효력규정에 위반한 경우에는 무효로 되지만 단속규정에 위반한 경우에는 원칙적으로 무효가 아니다.","w":"단속규정은 위반하면 처벌 등 제재를 받을 뿐 법률행위의 사법상 효력은 유지되는 것이 원칙이다.","c":"상","v":1},"세무사2017_54-57-4":{"f":"동기가 불법인 경우에는 그 동기가 표시되거나 상대방이 인식한 때에 법률행위는 무효로 된다.","w":"동기의 불법은 동기가 표시되었거나 상대방이 알았을 때 법률행위를 무효로 만든다.","c":"상","v":1},"세무사2017_54-57-5":{"f":"법률행위의 목적이 사회적 타당성을 결여하였다면 개별적인 강행법규에 위반하지 않았더라도 그 법률행위는 무효이다.","w":"제103조는 개별 강행법규와 별개로 사회질서에 반하는 법률행위를 무효로 한다.","c":"상","v":1},"세무사2021_58-75-4":{"f":"하나의 법률관계에 관해 서로 모순된 내용을 담은 여러 개의 계약서가 순차로 작성되었으나 그 우열관계가 정해지지 않았다면 원칙적으로 나중에 작성된 계약서가 우선한다.","w":"동일한 사항에 대해 문서가 중복해 작성되었다면 마지막 문서에 당사자의 최종 의사가 담겨 있다고 본다.","c":"상","v":1},"세무사2021_58-77-2":{"f":"경매에는 민법 제104조가 적용되지 않는다.","w":"판례는 경매에 불공정한 법률행위에 관한 제104조가 적용되지 않는다고 본다.","c":"상","v":1},"세무사2022_59-61-1":{"f":"법률행위가 성립하기 위해서는 성립 당시에 법률행위의 목적이 확정되어 있거나 장차 확정할 수 있어야 한다.","w":"목적이 성립 당시에 이미 확정되어 있을 필요는 없다.","c":"상","v":1},"세무사2022_59-61-3":{"f":"법률행위의 목적이 사회적 타당성을 결여하였다면 개별적인 강행법규에 위반하지 않았더라도 그 법률행위는 무효이다.","w":"사회질서에 반하는 법률행위는 제103조에 따라 무효이다.","c":"상","v":1},"세무사2022_59-61-4":{"f":"법률행위는 효력규정에 위반하는 경우에는 무효로 되지만 단속규정에 위반하는 경우에는 원칙적으로 무효가 아니다.","w":"단속규정을 위반한 법률행위는 제재를 받을 수 있지만 사법상 효력은 유지된다.","c":"상","v":1},"세무사2022_59-61-5":{"f":"강행규정을 위반하여 계약이 무효이면 계약상대방이 선의ㆍ무과실이라도 진의 아닌 의사표시의 법리가 적용될 수 없다.","w":"강행규정 위반으로 인한 무효는 상대방의 선의ㆍ무과실로 구제되지 않는다. 제107조 제2항을 끌어와 유효로 만들 수 없다.","c":"중","v":1},"세무사2022_59-62-5":{"f":"계약당사자의 자유의사에 의하여 불가항력으로 인한 손해를 계약당사자의 일방만이 부담한다는 특약을 한 경우에도, 특별한 사정이 없는 한 반사회질서의 법률행위에 해당하지 않는다.","w":"위험부담을 한쪽이 지기로 한 특약은 계약자유 범위에 속하며 그것만으로 반사회질서가 되지는 않는다.","c":"중","v":1},"세무사2022_59-65-5":{"f":"계약당사자 쌍방이 모두 X물건을 계약의 목적물로 삼았으나 계약서에는 착오로 Y물건을 목적물로 기재한 경우, X물건에 관하여 계약이 성립한 것으로 보아야 한다.","w":"당사자 모두가 같은 대상을 생각했다면 잘못 기재된 표시와 관계없이 그 의사대로 계약이 성립한다.","c":"상","v":1},"세무사2022_59-66-3":{"f":"불공정한 법률행위에 관한 민법의 규정은 비법인사단의 총회 결의에도 적용될 수 있다.","w":"불공정한 법률행위에 관한 제104조는 단독행위나 합동행위 등 법률행위 일반에 적용될 수 있다.","c":"중","v":1},"세무사2023_60-55-3":{"f":"무권리자와의 거래로 권리를 취득하는 것이 가능하다.","w":"선의취득 같은 제도로 무권리자와 거래한 상대방이 권리를 취득할 수 있다.","c":"상","v":1},"세무사2023_60-56-2":{"f":"강행법규에 위반하여 무효인 법률행위는 당사자가 추인하더라도 효력이 생기지 않는다.","w":"무효인 법률행위는 추인해도 유효가 되지 않는다(제139조).","c":"상","v":1},"세무사2023_60-56-3":{"f":"매매계약이 강행법규에 위반되어 무효인 경우에는 표현대리가 성립할 수 없다.","w":"표현대리는 대리권이 없는 대리행위에 본인 책임을 지우는 제도다. 계약 자체가 무효이면 표현대리가 성립하는 문제가 아니다.","c":"중","v":1},"세무사2023_60-56-4":{"f":"공인중개사 자격이 없는 자가 우연한 기회에 단 1회 타인 간의 거래행위를 중개한 경우, 그에 따른 중개수수료 지급약정이 부동산 중개보수 제한에 관한 규정들에 위반하였더라도 중개보수 약정은 규정의 한도를 초과하는 부분에서 무효가 되지는 않는다.","w":"판례는 중개를 업으로 하지 않고 우연히 1회 중개한 경우 그 수수료 약정이 강행법규 위반으로 무효가 되지는 않고, 약정 보수가 부당하게 과다하면 신의칙에 따라 상당한 범위로 감액될 뿐이라고 본다.","c":"중","v":1},"세무사2023_60-56-5":{"f":"법률행위의 효력요건은 원칙적으로 법률행위의 효과를 다투는 자가 그 흠결을 증명하여야 한다.","w":"법률행위의 효과를 주장하는 자는 성립요건을 증명하고, 효력요건을 갖추지 못했다는 사정(무효 사유 등)은 그 효과를 부정하는 쪽이 증명한다.","c":"중","v":1},"세무사2023_60-57-5":{"f":"법률행위의 성립과정에서 강박이라는 불법적 방법이 사용되었다는 이유만으로는 반사회적 법률행위가 될 수 없다.","w":"판례는 성립과정에 강박 같은 불법이 있었다는 사정만으로 제103조 위반으로 보지 않고 제110조의 강박에 의한 의사표시로 다룬다.","c":"상","v":1},"세무사2023_60-58-2":{"f":"무경험은 해당 법률행위가 속한 특정영역이 아니라 거래 일반의 경험부족을 의미한다.","w":"무경험이란 어느 특정 영역의 경험 부족이 아니라 거래 일반에 대한 경험 부족이다.","c":"상","v":1},"세무사2024_61-56-1":{"f":"건물에 관한 매매계약 체결 후, 그 건물이 전부 소실되었더라도 그 계약은 유효하다.","w":"계약 성립 뒤에 목적물이 없어진 것은 후발적 불능이어서 계약이 무효가 되지 않고 채무불이행이나 위험부담으로 처리한다.","c":"상","v":1},"세무사2024_61-59-5":{"f":"대리인에 의하여 행해진 법률행위가 불공정한 법률행위에 해당하는지 여부를 판단함에 있어서 경솔ㆍ무경험은 대리인을 기준으로 하고 궁박은 본인을 기준으로 판단하여야 한다.","w":"궁박은 본인의 사정을 기준으로 하고, 경솔과 무경험은 대리인을 기준으로 판단한다.","c":"상","v":1},"세무사2025_62-51-3":{"f":"규범적 해석은 상대방의 입장에서 객관적으로 합리적인 사람이 이해하는 대로 계약의 내용을 결정하는 것이다.","w":"규범적 해석은 표시를 상대방이 이해할 수 있는 객관적 의미대로 해석하는 방법이고 상대방의 주관적 이해에 따르지 않는다.","c":"상","v":1},"세무사2025_62-54-1":{"f":"2중매매를 하는 매도인의 배임행위에 대리인이 적극가담하면서 본인을 위하여 부동산을 매수한 경우, 본인이 그러한 사정을 과실 없이 몰랐더라도 위 부동산 매매계약은 무효이다.","w":"대리인이 적극 가담한 경우 대리행위의 반사회성은 대리인을 기준으로 판단하므로 본인이 몰랐다는 사정이 무효를 막지 못한다.","c":"상","v":1},"세무사2025_62-54-2":{"f":"피보험자를 살해하여 보험금을 부정취득할 목적으로 생명보험계약을 체결한 경우, 보험회사가 그러한 동기를 인식하지 못했더라도 해당 보험계약은 무효이다.","w":"보험금을 노린 범죄 목적의 보험계약은 계약 자체가 사회질서에 반하는 것이어서 상대방의 인식 여부와 관계없이 무효다.","c":"중","v":1},"세무사2025_62-54-3":{"f":"강제집행을 면할 목적으로 부동산에 허위의 근저당권설정등기를 경료하는 행위는 반사회적 법률행위로 볼 수 없다.","w":"강제집행을 피하려는 허위 근저당 설정은 제103조 위반이 아니다. 허위표시로서 무효가 될 뿐이다.","c":"상","v":1},"세무사2025_62-54-4":{"f":"변호사가 민사사건에서 성공보수약정을 하는 것은 공서양속 위반행위로 볼 수 없다.","w":"판례는 형사사건의 성공보수약정만 사회질서에 반해 무효로 보고 민사사건의 성공보수약정은 유효로 본다.","c":"상","v":1},"세무사2025_62-57-2":{"f":"피해자가 스스로 초래한 궁박도 불공정한 법률행위의 요건인 궁박에 포함될 수 있다.","w":"궁박의 원인에 제한이 없어 피해자 스스로 초래한 곤궁 상태도 궁박이 될 수 있다.","c":"중","v":1},"세무사2025_62-70-2":{"f":"사단법인 사원권의 양도ㆍ상속금지에 관한 규정은 임의규정이다.","w":"사원의 지위는 양도 또는 상속할 수 없다는 제56조는 정관으로 달리 정할 수 있는 임의규정이라는 것이 판례다.","c":"상","v":1},"세무사2026_63-54-2":{"f":"법인 아닌 개인이 농지를 취득하는 경우, 농지취득자격증명은 농지취득의 원인이 되는 법률행위의 효력발생요건이 아니다.","w":"농지취득자격증명은 소유권이전등기를 신청할 때 필요한 서류일 뿐, 매매 같은 원인 계약의 효력과는 관계가 없다.","c":"상","v":1},"세무사2026_63-57-1":{"f":"보험금을 사취할 목적으로 다수의 보험계약을 체결한 경우, 그 보험계약의 무효는 선의의 제3자에게도 대항할 수 있다.","w":"반사회질서 법률행위의 무효는 절대적이어서 선의의 제3자에게도 주장할 수 있다.","c":"상","v":1},"세무사2026_63-57-2":{"f":"강제집행을 면할 목적으로 부동산에 허위의 근저당권설정등기를 한 행위는 반사회 질서의 법률행위가 아니다.","w":"강제집행면탈 목적의 허위 근저당 설정은 제103조 위반이 아니다.","c":"상","v":1},"세무사2026_63-57-3":{"f":"부첩관계인 부부생활의 종료를 해제조건으로 하는 증여계약은 무효이다.","w":"부첩관계의 종료를 해제조건으로 한 증여는 조건이 사회질서에 반하므로 조건만 무효가 되는 것이 아니라 증여계약 전체가 무효다(제151조 제1항).","c":"상","v":1},"세무사2026_63-57-5":{"f":"해외파견된 근로자가 귀국일로부터 일정기간 소속회사에 근무하여야 한다는 약정은 반사회질서의 법률행위가 아니다.","w":"연수나 파견 비용을 보전하려는 의무근무 약정은 직업선택의 자유를 지나치게 제한하지 않는 한 유효하다.","c":"상","v":1},"세무사2026_63-58-3":{"f":"현저하게 공정을 잃은 법률행위라도 궁박, 경솔 또는 무경험으로 이루어진 것으로 추정되지 않는다.","w":"급부 사이에 현저한 불균형이 있다는 사정만으로는 피해자의 궁박, 경솔, 무경험이 추정되지 않는다.","c":"상","v":1},"세무사2016_53-65-1":{"f":"상대방 없는 의사표시에 대해서는 표시행위가 완료된 때 효력이 생기고 도달주의가 적용되지 않는다.","w":"도달주의는 상대방 있는 의사표시에 적용되는 원칙이다. 상대방이 없으면 표시행위가 끝난 때 효력이 생긴다.","c":"상","v":1},"세무사2016_53-65-3":{"f":"의사표시가 도달하였다고 하기 위해서는 상대방이 통지를 현실적으로 수령하였거나 내용을 알았을 필요는 없고, 알 수 있는 객관적 상태에 놓이면 충분하다.","w":"도달은 상대방의 지배 영역에 들어가 내용을 알 수 있는 객관적 상태에 이른 것을 말한다.","c":"상","v":1},"세무사2016_53-65-4":{"f":"표의자가 과실 없이 상대방을 알지 못한 경우에 한하여 의사표시는 민사소송법 공시송달의 규정에 의해 송달할 수 있다.","w":"표의자가 과실로 상대방을 알지 못한 때에는 공시송달을 할 수 없다(제113조).","c":"상","v":1},"세무사2016_53-65-5":{"f":"의사표시를 받은 자가 제한능력자인 경우, 그 법정대리인이 의사표시의 도달을 안 후에는 표의자는 그 의사표시로써 대항할 수 있다.","w":"법정대리인이 도달 사실을 안 뒤에는 제한능력자에게도 대항할 수 있다(제112조 단서).","c":"상","v":1},"세무사2016_53-66-1":{"f":"부동산의 매매에 있어서 시가에 대한 착오는 이른바 동기의 착오로서 법률행위의 중요부분에 관한 착오에 해당하지 않는다.","w":"시가는 매매 의사를 정하게 된 동기에 해당하며, 판례는 시가에 관한 착오로 취소할 수 없다고 본다.","c":"상","v":1},"세무사2017_54-60-4":{"f":"표시된 법률행위와 다른 법률행위를 은닉할 목적은 통정허위표시의 요건이 아니다.","w":"통정허위표시는 진의와 표시의 불일치를 상대방과 합의하고 있으면 성립하고, 다른 행위를 감추려는 목적은 필요 없다.","c":"상","v":1},"세무사2017_54-61-2":{"f":"표의자가 의사표시를 발송한 후 사망한 경우에도 그 의사표시의 효력에는 영향이 없다.","w":"발신 후 표의자가 사망하거나 행위능력을 상실해도 의사표시의 효력에는 영향이 없다(제111조 제2항).","c":"상","v":1},"세무사2017_54-64-2":{"f":"통정허위표시인 매매계약에 따라 대금을 지급한 경우, 그 계약은 무효이므로 대금의 반환을 청구할 수 있다.","w":"허위표시는 무효이므로 이행된 급부는 부당이득으로 반환을 청구할 수 있다.","c":"상","v":1},"세무사2017_54-66-2":{"f":"진의 아닌 의사표시는 진의와 표시가 일치하지 않음을 표의자가 알고 있는 경우에 성립한다.","w":"표의자가 불일치를 알지 못했다면 착오이고 진의 아닌 의사표시가 아니다.","c":"상","v":1},"세무사2021_58-73-5":{"f":"상대방의 피용자가 대리권이 없다면 그 피용자의 사기는 제3자의 사기에 해당한다.","w":"상대방의 대리인이 아닌 피용자의 기망은 제3자의 사기이므로 상대방이 알았거나 알 수 있었을 때만 취소할 수 있다.","c":"중","v":1},"세무사2021_58-76-5":{"f":"제3자가 악의이더라도 제3자로부터의 전득자가 선의라면 전득자에게 통정허위표시의 무효로 대항할 수 없다.","w":"악의의 제3자로부터 취득한 선의의 전득자도 제108조 제2항의 제3자로 보호된다.","c":"상","v":1},"세무사2021_58-78-3":{"f":"경과실로 착오에 빠진 표의자가 착오를 이유로 법률행위를 취소하더라도 표의자는 불법행위책임을 지지 않는다.","w":"착오 취소는 정당한 권리 행사여서 상대방에게 불법행위책임을 지지 않는다. 민법에 취소에 따른 손해배상을 정한 규정이 없다.","c":"상","v":1},"세무사2021_58-79-2":{"f":"법률상 장애로 자기 명의로 대출받을 수 없는 자를 위하여 대출금채무자로서의 명의를 빌려준 자의 대출기관에 대한 채무부담의 의사표시는 원칙적으로 비진의표시가 아니다.","w":"명의를 빌려준 자도 채무를 부담하겠다는 의사가 있어 진의와 표시가 일치한다.","c":"상","v":1},"세무사2022_59-57-5":{"f":"상대방이 표의자의 착오를 알면서 이를 이용한 경우에는 표의자에게 중과실이 있더라도 표의자는 착오에 의한 의사표시를 취소할 수 있다.","w":"상대방이 착오를 알고 이용한 경우에는 표의자의 중과실이 있어도 취소할 수 있다는 것이 판례다.","c":"상","v":1},"세무사2022_59-58-4":{"f":"본인의 피용자의 기망행위로 상대방이 매매계약을 체결한 경우, 상대방은 본인이 기망행위를 알았거나 알 수 있었을 때에 한하여 매매계약을 취소할 수 있다.","w":"대리인이 아닌 피용자의 기망은 제3자의 사기라서 상대방이 알았거나 알 수 있었어야 취소할 수 있다.","c":"중","v":1},"세무사2022_59-59-4":{"f":"미성년자에게 매매계약 취소의 의사표시가 도달한 경우 미성년자는 그 의사표시의 도달을 주장할 수 있다.","w":"제한능력자에게는 의사표시의 도달을 대항하지 못할 뿐이고 제한능력자 쪽에서 도달을 주장하는 것은 가능하다(제112조).","c":"중","v":1},"세무사2022_59-63-1":{"f":"진의 아닌 의사표시는 원칙적으로 유효하다.","w":"진의 아닌 의사표시는 표시된 대로 효력이 생기는 것이 원칙이다(제107조 제1항 본문).","c":"상","v":1},"세무사2022_59-63-2":{"f":"강박에 의해 증여를 한 경우, 증여의 의사가 있었으므로 그 증여는 진의 아닌 의사표시가 아니다.","w":"강박에 의한 의사표시는 의사표시의 하자로 취소할 수 있을 뿐이고 진의 아닌 의사표시와는 구별된다.","c":"상","v":1},"세무사2022_59-63-4":{"f":"법률상 장애로 자기 명의로 대출받을 수 없는 자를 위해 대출금 채무자로서의 명의를 빌려준 자의 대출기관에 대한 채무부담의 의사표시는 원칙적으로 진의 아닌 의사표시가 아니다.","w":"명의대여자도 채무를 부담한다는 효과의사가 있으므로 진의 아닌 의사표시가 아니다.","c":"상","v":1},"세무사2022_59-63-5":{"f":"진의와 표시가 일치하지 않음을 표의자가 알고 있는 경우에 진의 아닌 의사표시가 성립한다.","w":"진의 아닌 의사표시는 표의자가 불일치를 알고 있어야 성립한다.","c":"상","v":1},"세무사2023_60-59-2":{"f":"진의 아닌 의사표시는 표시된 의사와 내심의 의사가 다르다는 것을 표의자가 인식한 경우를 말한다.","w":"불일치를 표의자가 인식하지 못한 경우는 착오에 해당한다.","c":"상","v":1},"세무사2023_60-59-3":{"f":"진의 아닌 의사표시임을 표의자의 상대방이 알고 있었다면 그 의사표시는 무효이다.","w":"상대방이 표의자의 진의 아님을 알았거나 알 수 있었다면 무효다(제107조 제1항 단서).","c":"상","v":1},"세무사2023_60-59-4":{"f":"혼인할 의사 없이 혼인의 청약을 하였다면 상대방이 청약을 믿고 승낙하였더라도 혼인의 합의는 무효이다.","w":"혼인에는 진의 아닌 의사표시 규정이 적용되지 않고, 혼인할 의사가 없으면 합의가 무효이다.","c":"중","v":1},"세무사2023_60-59-5":{"f":"특정 물건을 매도할 의사로 증여한다는 청약을 하였는데 상대방이 청약을 믿고 승낙을 하였다면 증여계약이 체결된 것이다.","w":"진의 아닌 의사표시는 표시된 대로 효력이 있으므로(제107조 제1항 본문), 상대방이 진의를 모르고 승낙했다면 표시된 내용인 증여계약이 성립한다. 내심에만 있던 매매 의사로는 매매계약이 성립하지 않는다.","c":"상","v":1},"세무사2023_60-60-4":{"f":"가장의 채권양도에서 아직 채무를 변제하지 않은 채무자는 민법 제108조 제2항의 제3자에 해당하지 않는다.","w":"제3자는 허위표시에 기초해 새로운 법률상 이해관계를 맺은 사람이다. 가장양수인에 대한 채무자는 이에 해당하지 않는다.","c":"상","v":1},"세무사2023_60-61-5":{"f":"과실로 인한 착오를 이유로 법률행위를 취소한 자는 그 취소로 발생한 상대방의 손해를 배상할 책임이 없다.","w":"착오로 취소하는 것은 정당한 권리 행사여서 손해배상의무가 없다.","c":"상","v":1},"세무사2023_60-62-4":{"f":"취소를 원하는 표의자가 자신의 착오에 중대한 과실이 없음을 증명할 필요가 없고, 상대방이 표의자의 중대한 과실을 증명하여야 한다.","w":"표의자의 중대한 과실은 취소를 막으려는 상대방이 증명한다.","c":"상","v":1},"세무사2023_60-63-3":{"f":"상대방 있는 의사표시에 관하여 제3자가 사기를 행한 경우에 상대방이 그 사실을 알았거나 알 수 있었던 경우에 한하여 표의자는 그 의사표시를 취소할 수 있다.","w":"제3자의 사기는 상대방이 알았거나 알 수 있었을 때에만 취소할 수 있다(제110조 제2항).","c":"상","v":1},"세무사2023_60-64-2":{"f":"유언은 유언자가 사망한 때에 효력이 생긴다.","w":"유언은 유언자의 사망 시 효력이 있다(제1073조 제1항).","c":"상","v":1},"세무사2024_61-60-4":{"f":"의사표시의 상대방이 의사표시를 받은 때에 제한능력자라도, 그 상대방의 법정대리인이 의사표시가 도달한 사실을 안 후에는 의사표시자는 그 의사표시로써 대항할 수 있다.","w":"법정대리인이 도달 사실을 안 후에는 제한능력자에게도 대항할 수 있다(제112조).","c":"상","v":1},"세무사2024_61-61-1":{"f":"통정허위표시의 당사자 사이에는 그 의사표시에 따른 권리의무가 발생하지 않는다.","w":"통정허위표시는 당사자 사이에서 무효이다(제108조 제1항).","c":"상","v":1},"세무사2024_61-61-2":{"f":"통정허위표시인 법률행위를 대상으로 채권자취소권을 행사할 수 있다.","w":"허위표시로 무효여도 채권자취소권의 대상이 될 수 있다는 것이 판례다.","c":"상","v":1},"세무사2024_61-61-4":{"f":"통정허위표시로 대항할 수 없는 제3자의 ‘악의’는 허위표시의 무효를 주장하는 자가 증명해야 한다.","w":"제3자의 선의는 추정되므로 무효를 주장하려는 사람이 제3자의 악의를 증명해야 한다.","c":"상","v":1},"세무사2024_61-61-5":{"f":"제3자가 통정허위표시에 대항할 수 있기 위해서는 선의이면 충분하고 과실이 없을 필요는 없다.","w":"제108조 제2항의 선의의 제3자는 무과실까지 요구되지 않는다.","c":"상","v":1},"세무사2024_61-64-3":{"f":"기망행위를 한 자가 상대방의 대리인인 경우에는 제3자에 의한 사기가 아니다.","w":"상대방의 대리인이 한 기망은 상대방 자신의 사기와 같이 취급해 제3자 사기에 해당하지 않는다.","c":"상","v":1},"세무사2025_62-55-4":{"f":"대리권이 남용되어 민법 제107조 제1항 단서를 유추적용하는 경우, 선의의 제3자 보호에 관한 동조 제2항도 유추적용된다.","w":"판례는 대리권 남용에서 제107조 제1항 단서뿐 아니라 제2항도 유추적용한다.","c":"상","v":1},"세무사2025_62-56-1":{"f":"장래에 발생할 막연한 사정을 기대하고 법률행위를 한 경우 그 기대와 다른 사정이 발생한 때에도 특별한 사정이 없는 한 착오를 이유로 법률행위를 취소할 수 없다.","w":"막연한 장래 기대가 어긋난 것은 동기의 착오에 불과하다. 동기가 표시되는 등의 사정이 없으면 취소할 수 없다.","c":"상","v":1},"세무사2025_62-59-3":{"f":"횡령의 범죄를 저지른 자로부터 적절한 손해배상을 얻기 위하여 그를 횡령죄로 고소한 경우 이러한 고소는 원칙적으로 위법한 강박에 해당하지 않는다.","w":"정당한 권리 실현을 위한 고소는 위법한 강박이 아니다. 부정한 이익을 얻을 목적으로 한 때에만 위법하다.","c":"상","v":1},"세무사2025_62-60-4":{"f":"의사표시의 발송 후 도달 전에 표의자에 대한 성년후견이 개시되었더라도 그 의사표시는 도달하면 효력을 발한다.","w":"표의자가 발신 후 행위능력을 상실해도 의사표시의 효력에 영향이 없다(제111조 제2항).","c":"상","v":1},"세무사2026_63-59-1":{"f":"진의와 표시의 불일치를 표의자가 알고 있는 경우에 진의 아닌 의사표시가 성립한다.","w":"표의자가 불일치를 알지 못했다면 착오이다.","c":"상","v":1},"세무사2026_63-59-2":{"f":"진의 아닌 의사표시는 원칙적으로 유효하다.","w":"제107조 제1항 본문에 따라 표시된 대로 효력이 있다. 상대방이 진의 아님을 알았거나 알 수 있었을 때만 무효가 된다.","c":"상","v":1},"세무사2026_63-59-4":{"f":"대리행위에서 진의 아닌 의사표시인지 여부는 대리인을 표준으로 정한다.","w":"대리행위의 하자 유무는 대리인을 기준으로 판단한다(제116조 제1항).","c":"상","v":1},"세무사2026_63-59-5":{"f":"진의 아닌 의사표시의 규정은 상대방 있는 단독행위에도 적용된다.","w":"제107조는 계약뿐 아니라 상대방 있는 단독행위에도 적용된다.","c":"상","v":1},"세무사2026_63-60-2":{"f":"통정허위표시의 무효로부터 보호되는 선의의 제3자는 과실이 있더라도 보호된다.","w":"제108조 제2항의 선의의 제3자는 무과실까지 요구되지 않는다.","c":"상","v":1},"세무사2026_63-63-1":{"f":"채권양도의 통지와 같은 관념의 통지에도 도달주의 원칙이 적용된다.","w":"의사표시에 관한 도달주의는 채권양도 통지 같은 관념의 통지에도 준용된다.","c":"상","v":1},"세무사2026_63-63-2":{"f":"의사표시의 발신 후 표의자가 사망한 경우에도, 그 의사표시는 상대방에게 도달하면 효력이 발생한다.","w":"발신 후 표의자의 사망은 의사표시의 효력에 영향이 없다(제111조 제2항).","c":"상","v":1},"세무사2026_63-63-3":{"f":"무권대리인의 상대방이 본인에게 추인 여부의 확답을 최고한 경우, 그 최고는 본인에게 도달한 때 효력이 발생한다.","w":"최고도 상대방 있는 의사표시이므로 도달한 때 효력이 생긴다.","c":"상","v":1},"세무사2026_63-63-5":{"f":"의사표시를 받은 상대방이 제한능력자이더라도 그의 법정대리인이 의사표시의 도달사실을 안 후에는 표의자는 그 의사표시로써 대항할 수 있다.","w":"법정대리인이 도달 사실을 안 후에는 제한능력자에게도 대항할 수 있다(제112조 단서).","c":"상","v":1},"세무사2016_53-67-4":{"f":"예금계약 체결을 위임받은 자의 대리권에는 그 예금을 처분할 수 있는 대리권이 당연히 포함되지는 않는다.","w":"예금계약을 맺을 권한과 예금을 인출하거나 처분할 권한은 별개이다. 처분은 따로 수권을 받아야 한다.","c":"중","v":1},"세무사2016_53-69-2":{"f":"현명은 명시적으로뿐 아니라 묵시적으로도 할 수 있다.","w":"대리인이 본인을 위한 것임을 표시하지 않았어도 상대방이 알았거나 알 수 있었다면 본인에게 효력이 생긴다(제115조 단서).","c":"상","v":1},"세무사2016_53-69-3":{"f":"대리행위가 불공정한 법률행위(민법 제104조)에 해당하는지 여부를 판단함에 있어서, 궁박은 본인을 기준으로 하여야 한다.","w":"경솔과 무경험은 대리인을 기준으로 판단하고, 궁박은 본인을 기준으로 판단한다.","c":"상","v":1},"세무사2016_53-69-4":{"f":"특정한 법률행위를 위임받은 임의대리인이 본인의 지시에 좇아 그 행위를 한 때에, 본인은 자기가 과실로 인하여 알지 못한 사정에 관하여 대리인의 부지를 주장하지 못한다.","w":"본인의 지시에 따라 대리인이 행위한 때에는 본인이 안 사정뿐 아니라 과실로 알지 못한 사정에 관해서도 대리인이 몰랐다고 주장하지 못한다(제116조 제2항).","c":"상","v":1},"세무사2016_53-69-5":{"f":"대리인이 상대방에게 강박을 행한 경우, 본인이 그 사실을 알았는지와 관계없이 상대방은 그 의사표시를 취소할 수 있다.","w":"대리인의 강박은 제3자의 강박이 아니라 본인 자신의 행위와 같이 취급되어 본인의 인식 여부를 묻지 않는다.","c":"상","v":1},"세무사2016_53-72-1":{"f":"복대리인은 대리인이 선임한 본인의 대리인이다.","w":"복대리인은 대리인의 대리인이 아니라 본인의 대리인이다.","c":"상","v":1},"세무사2017_54-59-3":{"f":"대리는 법률행위에 한하여 인정되고, 대리인이 행한 불법행위에 대하여는 대리가 성립하지 않는다.","w":"불법행위나 사실행위는 대리의 대상이 아니다.","c":"상","v":1},"세무사2017_54-62-2":{"f":"법률행위에 의하여 대리권을 수여하는 경우, 대리인은 행위능력자일 필요가 없다.","w":"대리인은 행위능력자임을 요하지 않는다(제117조).","c":"상","v":1},"세무사2017_54-63-1":{"f":"乙은 부득이한 사유가 없으면 甲의 승낙을 얻지 않고서 丙을 복대리인으로 선임할 수 없다.","w":"임의대리인은 본인의 승낙이나 부득이한 사유가 있어야 복대리인을 선임할 수 있다(제120조).","c":"상","v":1},"세무사2017_54-63-2":{"f":"乙이 부득이한 사유로 丙을 복대리인으로 선임하였더라도 乙은 甲에 대하여 丙의 선임감독에 관한 책임을 진다.","w":"임의대리인이 복대리인을 선임하면 본인에 대해 선임ㆍ감독상의 책임을 진다(제121조 제1항).","c":"상","v":1},"세무사2017_54-63-3":{"f":"乙이 甲의 지명에 의하여 丙을 복대리인으로 선임한 경우에도 乙은 대리인의 지위를 상실하지 않는다.","w":"복대리인 선임은 대리권을 소멸시키지 않는다.","c":"상","v":1},"세무사2017_54-63-5":{"f":"丙이 적법한 대리행위를 통하여 아파트를 임차한 경우, 그 효과는 甲에게 귀속한다.","w":"복대리인은 본인의 대리인이므로 복대리행위의 효과는 대리인이 아니라 본인에게 귀속한다.","c":"상","v":1},"세무사2017_54-67-1":{"f":"본인의 허락이 있으면 대리인은 자기계약이나 쌍방대리를 할 수 있다.","w":"제124조는 본인의 허락이 있는 경우를 금지에서 제외한다.","c":"상","v":1},"세무사2017_54-67-2":{"f":"자기계약에 따라 본인이 대리인에 대하여 부담하는 채무를 대리인이 면제하여 주는 경우에는 본인의 동의를 받을 필요가 없다.","w":"본인에게 이익만 주는 행위는 금지 대상이 아니다. 제124조는 본인의 이익을 해칠 염려가 있는 경우를 막는 규정이다.","c":"중","v":1},"세무사2017_54-67-3":{"f":"자기계약ㆍ쌍방대리의 금지에 관한 규정은 법정대리에도 적용된다.","w":"제124조는 임의대리와 법정대리 모두에 적용된다.","c":"상","v":1},"세무사2017_54-67-5":{"f":"친권자가 그 소유 부동산을 미성년인 아들에게 증여하는 행위는 자기계약에 해당하나 미성년자에게 이익만 주는 행위이므로 유효하다.","w":"미성년자에게 불이익이 없는 단순 증여는 이해상반행위가 아니어서 친권자가 대리해도 유효하다.","c":"중","v":1},"세무사2021_58-61-1":{"f":"미성년자인 대리인은 제한능력자임을 이유로 본인과의 위임계약을 취소할 수 있다.","w":"대리인이 제한능력자여도 대리행위는 취소할 수 없지만, 본인과 대리인 사이의 위임계약은 제한능력을 이유로 취소할 수 있다.","c":"중","v":1},"세무사2021_58-62-2":{"f":"대리인이 본인을 위한 것임을 표시하지 않은 경우에도 상대방이 대리행위임을 알 수 있었다면 본인에게 효력이 미친다.","w":"현명하지 않았어도 상대방이 대리인으로서 한 행위임을 알았거나 알 수 있었다면 본인에게 효력이 생긴다(제115조 단서).","c":"상","v":1},"세무사2021_58-69-4":{"f":"새로운 이해관계를 창설하지 않는 채무의 이행에는 쌍방대리금지의 규정이 적용되지 않는다.","w":"채무 이행은 새로운 이해관계를 만들지 않아 본인에게 불이익이 없으므로 쌍방대리 금지의 예외다.","c":"상","v":1},"세무사2021_58-70-1":{"f":"법정대리인이 복대리인을 선임한 경우에는 그 선임 및 감독상 과실이 없더라도 복대리인의 행위에 대해 책임이 있다.","w":"법정대리인은 복대리인의 행위 전반에 대해 책임을 진다. 부득이한 사유로 선임했을 때만 선임ㆍ감독 책임으로 줄어든다(제122조).","c":"상","v":1},"세무사2021_58-70-3":{"f":"임의대리인은 본인의 승낙이 있거나 부득이한 사유가 있는 때가 아니면 복대리인을 선임하지 못한다.","w":"이 제한은 임의대리인에 관한 것이다(제120조). 법정대리인은 언제든 복대리인을 선임할 수 있다(제122조).","c":"상","v":1},"세무사2021_58-70-4":{"f":"임의대리의 목적인 법률행위의 성질이 대리인 자신에 의한 처리를 요하는 경우에는 본인이 복대리 금지의 의사를 명시하지 않았더라도 복대리인의 선임은 원칙적으로 허용되지 않는다.","w":"대리인 자신이 처리해야 하는 성질의 행위는 본인의 묵시적 승낙이 있는 경우를 제외하고는 복대리인을 선임할 수 없다.","c":"중","v":1},"세무사2021_58-70-5":{"f":"복대리인은 본인의 대리인이다.","w":"복대리인은 대리인의 대리인이 아니라 본인의 대리인이다(제123조).","c":"상","v":1},"세무사2022_59-68-2":{"f":"채권양도의 통지와 같은 관념의 통지에 대해서도 대리가 허용된다.","w":"관념의 통지는 의사표시 규정이 유추적용되어 대리가 허용된다.","c":"상","v":1},"세무사2022_59-71-3":{"f":"친권자의 재산을 자(子)에게 증여하면서 친권자가 수증자로서의 자(子)의 지위를 대리하는 것은 이해상반행위에 해당하지 않아 유효하다.","w":"미성년자가 이익만 얻는 증여는 이해상반행위가 아니어서 친권자가 대리해도 유효하다.","c":"중","v":1},"세무사2023_60-65-2":{"f":"수권행위는 본인의 단독행위이다.","w":"수권행위는 본인이 대리인에게 대리권을 주는 상대방 있는 단독행위이다.","c":"상","v":1},"세무사2023_60-66-1":{"f":"수권행위에 의해 대리권의 범위가 정해지지 않은 임의대리인은 처분행위를 할 수 없다.","w":"범위가 정해지지 않은 대리인은 보존행위와 대리 목적물의 성질을 변하지 않게 하는 이용ㆍ개량행위만 할 수 있다(제118조).","c":"상","v":1},"세무사2023_60-66-2":{"f":"본인에게 수인의 대리인이 존재한다면 이들은 원칙적으로 각자 대리행위를 할 수 있다.","w":"대리인이 여럿이면 각자 본인을 대리하는 것이 원칙이고 공동대리는 수권행위로 따로 정해야 한다(제119조).","c":"상","v":1},"세무사2023_60-66-4":{"f":"대리인이 본인의 허락 없이 본인을 위하여 자기와 계약하였다면 그 계약은 무권대리로서 본인의 추인이 있으면 유효가 될 수 있다.","w":"자기계약 위반은 무권대리행위로 보아 본인이 추인하면 유효하다. 확정적 무효가 아니다.","c":"중","v":1},"세무사2023_60-66-5":{"f":"부동산 매도의 대리인이 본인을 위한 매매계약시 상대방으로부터 강박을 당한 경우, 특별한 사정이 없는 한 그 대리인은 본인을 대리하여 해당 매매계약을 취소할 수 없다.","w":"매매 대리권에 취소권의 대리까지 당연히 포함되지는 않는다. 별도의 수권이 필요하다.","c":"중","v":1},"세무사2023_60-67-1":{"f":"현명 없는 대리인의 행위는 원칙적으로 자신을 위한 것으로 본다.","w":"현명하지 않은 의사표시는 대리인 자신을 위한 것으로 보는 것이 원칙이다(제115조 본문). 추정이 아닌 간주이다.","c":"상","v":1},"세무사2023_60-69-4":{"f":"본인과 복대리인 사이에는 내부적 계약관계가 인정되지 않지만, 복대리인은 본인에 대하여 대리인과 동일한 권리ㆍ의무가 있다.","w":"복대리인은 본인과 계약관계는 없어도 제123조에 따라 본인에 대해 대리인과 같은 권리ㆍ의무를 갖는다.","c":"상","v":1},"세무사2024_61-65-3":{"f":"乙이 甲의 지명에 의하여 丙을 복대리인으로 선임한 경우, 乙은 丙의 불성실함을 알고 이를 甲에게 알리지 않았다면 책임을 진다.","w":"지명에 따른 선임이라도 대리인이 복대리인의 부적임이나 불성실을 알고 본인에게 통지하거나 해임하지 않으면 책임을 진다(제121조 제2항).","c":"상","v":1},"세무사2024_61-66-5":{"f":"대리권은 그 원인된 법률관계가 종료하면 소멸한다.","w":"임의대리권은 원인이 된 법률관계가 끝나면 소멸한다(제128조).","c":"상","v":1},"세무사2024_61-67-2":{"f":"대여금의 영수권한만을 위임받은 대리인은 일반적으로 그 대여금채무의 일부를 면제할 권한은 없다.","w":"영수권한만 있는 대리인은 채무 면제처럼 채권을 소멸시키는 처분을 할 수 없다.","c":"상","v":1},"세무사2024_61-68-3":{"f":"매매위임장을 제시하였으나 매매계약서에 대리관계의 표시 없이 자신의 이름을 기재한 경우, 특별한 사정이 없는 한 소유자를 대리하여 매매계약을 체결한 것으로 보아야 한다.","w":"위임장을 제시하고 계약했다면 계약서에 대리인 자신의 이름만 적었어도 소유자를 대리해 매매한 것으로 본다는 것이 판례다.","c":"상","v":1},"세무사2025_62-73-1":{"f":"복대리인은 그 권한내에서 본인을 대리한다.","w":"복대리인은 대리인이 아니라 본인을 대리한다.","c":"상","v":1},"세무사2025_62-73-2":{"f":"대리인의 대리권이 소멸하면 복대리인의 대리권도 소멸한다.","w":"복대리권은 대리인의 대리권에 의존해서 대리권 소멸에 따라 함께 소멸한다.","c":"상","v":1},"세무사2025_62-73-3":{"f":"복대리인의 선임으로 대리인의 대리권은 소멸하지 않는다.","w":"복대리인을 선임해도 대리인의 대리권은 그대로 남는다.","c":"상","v":1},"세무사2025_62-73-5":{"f":"임의대리의 목적인 법률행위의 성질상 대리인 자신에 의한 처리가 필요하지 않은 경우, 본인이 복대리 금지의 의사를 명시하지 않았다면 복대리인의 선임에 관하여 본인의 묵시적인 승낙이 있는 것으로 볼 수 있다.","w":"대리인 본인이 처리할 필요가 없는 행위라면 복대리 금지가 명시되지 않은 한 복대리 선임에 대해 묵시적 승낙이 있는 것으로 본다.","c":"상","v":1},"세무사2025_62-74-2":{"f":"피성년후견인이 아닌 자가 대리인으로 된 후 그에 대해 성년후견이 개시된 경우, 그의 대리권은 소멸한다.","w":"대리인이 성년후견개시 심판을 받으면 대리권이 소멸한다(제127조).","c":"상","v":1},"세무사2026_63-64-2":{"f":"표현대리가 성립하는 경우에는 상대방에게 과실이 있더라도 과실상계의 법리를 유추 적용할 수 없다.","w":"표현대리가 성립하면 본인은 계약상 책임을 지고, 상대방의 과실을 이유로 책임을 감경할 수 없다.","c":"상","v":1},"세무사2026_63-65-5":{"f":"복대리인을 적법하게 선임한 대리인이 사망하면 특별한 사정이 없는 한 복대리권도 소멸한다.","w":"대리인이 사망하면 대리권이 소멸하고 복대리권도 따라 소멸한다.","c":"상","v":1},"세무사2026_63-66-5":{"f":"강제경매절차에서 경매입찰에 임하는 행위와 그에 부수된 권한을 수여받은 대리인은 경락인이 된 본인을 대리하여 채권자의 강제경매신청취하에 동의할 권한까지 가진다고 볼 수 없다.","w":"입찰 대리권에 경매신청 취하 동의권까지 포함된다고 볼 수 없다. 이는 별도의 수권이 필요하다.","c":"중","v":1},"세무사2016_53-70-2":{"f":"조건이 법률행위 당시 이미 성취한 것인 경우에는 그 조건이 정지조건이면 조건없는 법률행위로 한다.","w":"이미 성취된 정지조건은 조건 없는 법률행위가 되고, 이미 성취된 해제조건이 붙은 법률행위가 무효다(제151조 제2항).","c":"상","v":1},"세무사2016_53-76-5":{"f":"형성권적 기한이익 상실의 특약이 있는 경우에는 그 기한이익 상실사유가 발생하더라도 기한의 이익을 상실케 하는 채권자의 의사표시가 있어야 이행기 도래의 효과가 발생한다.","w":"형성권적 특약은 사유가 생겨도 채권자가 의사표시를 해야 기한이익이 없어진다. 사유 발생으로 당연히 이행기가 도래하는 것은 정지조건부 특약이다.","c":"상","v":1},"세무사2017_54-75-1":{"f":"기한의 이익은 원칙적으로 채무자의 이익을 위한 것으로 추정한다.","w":"기한은 채무자의 이익을 위한 것으로 추정한다(제153조 제1항).","c":"상","v":1},"세무사2017_54-75-2":{"f":"무이자 소비대차의 경우, 채무자가 기한의 이익을 가진다.","w":"무이자 소비대차에서는 채무자만 기한의 이익을 가지고, 채권자는 그 이익이 없다.","c":"상","v":1},"세무사2017_54-75-3":{"f":"이자부 소비대차의 경우, 채무자뿐 아니라 채권자도 기한의 이익을 가진다.","w":"이자를 받는 채권자에게도 기한까지 이자를 받을 이익이 있어 양쪽 모두 기한의 이익을 가진다.","c":"중","v":1},"세무사2017_54-75-4":{"f":"기한의 이익을 가지는 자는 기한이 도래하기 전에도 그 이익을 포기할 수 있다.","w":"기한의 이익은 포기할 수 있다. 다만 상대방의 이익을 해하지 못한다(제153조 제2항).","c":"상","v":1},"세무사2017_54-79-1":{"f":"불법조건이 붙어 있는 경우 그 법률행위의 전부가 무효로 된다.","w":"불법조건이 붙은 법률행위는 조건만 무효가 되는 것이 아니라 법률행위 전체가 무효다(제151조 제1항).","c":"상","v":1},"세무사2017_54-79-3":{"f":"불능조건이 정지조건이라면 그 법률행위는 무효이다.","w":"불능조건이 정지조건이면 법률행위가 무효이고 해제조건이면 조건 없는 법률행위가 된다(제151조 제3항).","c":"상","v":1},"세무사2017_54-79-4":{"f":"가족법상 법률행위에는 조건을 붙이는 것이 허용되지 않는 것이 원칙이다.","w":"혼인, 입양, 상속의 승인 등 신분행위는 조건에 친하지 않다.","c":"상","v":1},"세무사2017_54-79-5":{"f":"조건부 권리의 경우 아직 조건이 성취되기 전에도 처분할 수 있다.","w":"조건부 권리는 일반규정에 따라 처분, 상속, 보존, 담보로 할 수 있다(제149조).","c":"상","v":1},"세무사2021_58-67-4":{"f":"조건이 법률행위의 당시에 이미 성취할 수 없는 것인 경우에는 그 조건이 해제조건이면 조건 없는 법률행위로 하고 정지조건이면 무효로 한다.","w":"불능조건은 해제조건이면 조건 없는 법률행위이고, 정지조건이면 무효다.","c":"상","v":1},"세무사2021_58-68-3":{"f":"부관에 표시된 사실이 발생한 때에는 물론이고 반대로 발생하지 않은 것이 확정된 때에도 채무를 이행해야 한다고 보는 것이 합리적인 경우에 그 사실은 불확정기한으로 보아야 한다.","w":"사실이 불발생으로 확정된 때에도 이행해야 하는 경우라면 조건이 아니라 불확정기한이다.","c":"상","v":1},"세무사2022_59-70-5":{"f":"조건의 성취로 인하여 불이익을 받을 당사자가 신의칙에 반하여 조건의 성취를 방해한 경우, 조건은 방해가 없었더라면 성취되었을 것으로 추산되는 시점에 성취된 것으로 본다.","w":"방해행위가 있었던 때가 아니라 방해가 없었더라면 조건이 성취되었으리라고 추산되는 때에 성취된 것으로 본다(대법원 1998. 12. 22. 선고 98다42356 판결).","c":"상","v":1},"세무사2022_59-75-1":{"f":"기한은 원칙적으로 채무자의 이익을 위한 것으로 추정한다.","w":"기한은 채무자의 이익을 위한 것으로 추정한다(제153조 제1항).","c":"상","v":1},"세무사2022_59-75-2":{"f":"불확정한 사실이 발생한 때를 이행기한으로 정한 경우, 그 사실의 발생이 불가능하게 되었다면 기한은 도래한 것으로 보아야 한다.","w":"불확정기한은 사실이 발생한 때뿐 아니라 발생이 불가능해진 때에도 도래한다.","c":"상","v":1},"세무사2022_59-75-4":{"f":"어음·수표행위에도 시기(始期)를 붙일 수 있다.","w":"어음·수표행위에는 조건을 붙일 수 없지만 시기를 붙이는 것은 허용된다는 것이 통설이다. 시기는 반드시 도래하므로 유통성을 해치지 않는다.","c":"중","v":1},"세무사2022_59-75-5":{"f":"형성권적 기한이익 상실의 특약이 있는 경우, 기한이익의 상실사유가 발생하더라도 채권자의 의사표시가 있어야 채무자는 기한의 이익을 상실한다.","w":"형성권적 특약에서는 상실사유만으로는 부족하고 채권자가 의사표시를 해야 한다.","c":"상","v":1},"세무사2023_60-73-1":{"f":"특정의 제3자가 사망하면 증여를 하겠다는 계약은 불확정기한부 계약이다.","w":"사람의 사망은 반드시 오지만 그 시기만 불확정이므로 정지조건이 아니라 불확정기한이다.","c":"상","v":1},"세무사2023_60-73-2":{"f":"유언은 유언자의 사망으로 효력이 생기는 법률행위이고 사망을 정지조건으로 하는 법률행위가 아니다.","w":"유언의 효력이 사망 시 발생하는 것은 법이 정한 효력 발생 시기이고, 당사자가 붙인 조건이 아니다.","c":"중","v":1},"세무사2023_60-73-3":{"f":"물권행위도 조건을 붙일 수 있는 법률행위이다.","w":"물권행위에도 조건을 붙일 수 있다. 조건에 친하지 않은 것은 혼인, 입양 같은 신분행위와 어음행위 등이다.","c":"상","v":1},"세무사2023_60-73-5":{"f":"조건의 성취로 불이익을 받을 자가 과실로 신의성실에 반하여 조건의 성취를 방해한 때에도 조건의 성취가 의제될 수 있다.","w":"방해행위가 고의가 아니라 과실에 의한 것이어도 신의성실에 반하면 상대방은 조건이 성취된 것으로 주장할 수 있다(제150조 제1항, 대법원 1998. 12. 22. 선고 98다42356 판결).","c":"상","v":1},"세무사2023_60-74-5":{"f":"형성권적 기한이익상실의 특약이 있는 할부채무의 경우 그 요건이 충족된 후 채권자가 이행을 청구하는 의사표시를 한 때부터 채권 전액에 대해 소멸시효가 진행한다.","w":"채권자의 의사표시가 있어야 기한이익이 상실되므로 그 전에는 전액에 대해 소멸시효가 진행하지 않는다.","c":"상","v":1},"세무사2024_61-75-1":{"f":"정지조건부 법률행위는 조건이 성취되면 원칙적으로 그 효력은 성취한 때부터 생기고 소급하지 않는다.","w":"조건 성취의 효과는 특약이 없으면 소급하지 않는다(제147조 제1항).","c":"상","v":1},"세무사2024_61-75-2":{"f":"조건이 반사회적인 것이면 원칙적으로 법률행위 전부가 무효로 된다.","w":"조건이 선량한 풍속에 반하면 조건만 무효가 되는 것이 아니라 법률행위 전체가 무효가 된다.","c":"상","v":1},"세무사2024_61-75-3":{"f":"해제조건이 법률행위 당시 이미 성취된 것이면 그 법률행위는 무효이다.","w":"이미 성취한 해제조건이 붙은 법률행위는 무효가 된다(제151조 제2항).","c":"상","v":1},"세무사2024_61-75-5":{"f":"해제조건부 권리는 조건의 성취가 미정인 상태에서도 원칙적으로 담보로 제공할 수 있다.","w":"조건의 성취가 정해지지 않은 권리의무는 일반규정에 따라 처분, 상속, 보존, 담보로 할 수 있다(제149조).","c":"상","v":1},"세무사2025_62-71-3":{"f":"조건을 붙이는 것이 허용되지 아니하는 법률행위에 조건을 붙인 경우, 특별한 사정이 없으면 그 법률행위 전체가 무효로 된다.","w":"조건과 친하지 않은 법률행위에 조건을 붙이면 조건만이 아니라 법률행위 자체가 무효다.","c":"상","v":1},"세무사2025_62-72-1":{"f":"기한은 법률행위 효력의 발생이나 소멸을 장래의 확실한 사실의 성립 여부에 의존하게 하는 법률행위의 부관이다.","w":"기한은 장래 반드시 도래하는 사실에 의존하게 하는 부관이다. 불확실한 사실에 의존하게 하는 것은 조건이다.","c":"하","v":1},"세무사2025_62-72-2":{"f":"종기있는 법률행위는 기한이 도래한 때에 그 효력이 소멸한다.","w":"종기가 도래하면 법률행위의 효력이 소멸한다(제152조 제2항). 효력이 생기는 시기는 시기(始期)다.","c":"상","v":1},"세무사2025_62-72-3":{"f":"기한은 원칙적으로 채무자의 이익을 위한 것으로 추정한다.","w":"기한의 이익은 채무자에게 있는 것으로 추정한다(제153조 제1항).","c":"상","v":1},"세무사2025_62-72-4":{"f":"불확정한 사실이 발생한 때를 이행기한으로 정한 경우, 그 사실의 발생이 불가능하게 되었다면 기한은 도래한 것으로 보아야 한다.","w":"불확정기한은 사실 발생이 불가능해진 때에도 도래한다.","c":"상","v":1},"세무사2026_63-73-1":{"f":"정지조건부 법률행위는 조건이 성취되었을 때 비로소 효력이 발생한다.","w":"정지조건부 법률행위는 성립은 이미 되어 있고 조건 성취 때 효력이 생긴다.","c":"상","v":1},"세무사2026_63-73-2":{"f":"법률행위에 붙은 조건의 내용이 선량한 풍속에 반하는 것이면 법률행위 전부가 무효가 된다.","w":"불법조건이 붙은 법률행위는 조건만 무효가 되지 않고 법률행위 전체가 무효가 된다.","c":"상","v":1},"세무사2026_63-73-4":{"f":"조건이 법률행위 당시에 이미 성취한 것인 경우, 그 조건이 해제조건이면 그 법률행위는 무효로 한다.","w":"이미 성취한 해제조건은 법률행위를 무효로 하고, 이미 성취한 정지조건은 조건 없는 법률행위로 한다.","c":"상","v":1},"세무사2026_63-73-5":{"f":"조건의 성취로 인하여 불이익을 받을 당사자가 신의칙에 반하여 조건의 성취를 방해한 경우, 방해가 없었더라면 성취되었으리라고 추산되는 시점에 조건이 성취된 것으로 본다.","w":"방해행위를 한 때에 곧바로 성취가 의제되지 않고, 방해가 없었더라면 조건이 성취되었으리라고 추산되는 때에 성취된 것으로 본다(대법원 1998. 12. 22. 선고 98다42356 판결).","c":"상","v":1},"세무사2023_60-50-2":{"f":"정관상 임의적 기재사항을 변경할 때에도 정관변경절차를 거쳐야 한다.","w":"임의적 기재사항도 정관에 적은 이상 그 내용을 바꾸려면 정관변경의 절차를 밟아야 한다.","c":"상","v":1},"세무사2023_60-51-1":{"f":"법인은 해산하더라도 청산의 목적 범위 내에서는 권리능력을 가진다.","w":"해산한 법인은 청산이 끝날 때까지 청산 목적의 범위에서 존속한다(제81조).","c":"상","v":1},"세무사2023_60-51-2":{"f":"법원은 직권으로 청산인을 해임할 수 있다.","w":"법원은 중요한 사유가 있으면 직권으로, 또는 이해관계인이나 검사의 청구로 청산인을 해임할 수 있다(제84조).","c":"상","v":1},"세무사2023_60-51-3":{"f":"법인의 해산과 청산은 법원이 검사ㆍ감독한다.","w":"해산과 청산은 주무관청이 아니라 법원이 검사ㆍ감독한다(제95조).","c":"상","v":1},"세무사2023_60-51-4":{"f":"해산등기를 하지 않으면 법인의 해산 사실을 제3자에게 대항할 수 없다.","w":"법인의 해산은 등기를 해야 제3자에게 대항할 수 있다(제54조).","c":"상","v":1},"세무사2023_60-52-1":{"f":"일부 신도들이 사찰 운영에 반대하여 신도회에서 탈퇴한 경우에도 사찰이 분열된 것으로 인정되지 않는다.","w":"판례는 교회와 마찬가지로 사찰 같은 비법인사단의 분열을 인정하지 않는다.","c":"상","v":1},"세무사2024_61-47-1":{"f":"사원의 지위는 그 정관에서 양도할 수 있다고 규정하면 양도할 수 있다.","w":"사원 지위의 양도ㆍ상속 금지는 정관으로 달리 정할 수 있는 임의규정이다(제56조).","c":"상","v":1},"세무사2024_61-47-2":{"f":"정관에 이사의 해임사유에 관한 규정이 있더라도, 법인은 이사의 중대한 의무위반이 있으면 정관에서 정한 해임사유가 아니더라도 이사를 해임할 수 있다.","w":"판례는 정관에 해임사유가 정해져 있더라도, 이사에게 중대한 의무위반이 있거나 정상적인 사무집행을 할 수 없는 특별한 사정이 있으면 정관에 없는 사유로도 이사를 해임할 수 있다고 본다.","c":"상","v":1},"세무사2024_61-47-3":{"f":"이사에 결원이 생겨서 법인에게 손해가 생길 염려가 있는 경우, 법원은 임시이사를 선임하여야 한다.","w":"이사 결원으로 손해가 생길 염려가 있으면 법원이 이해관계인이나 검사의 청구로 임시이사를 선임한다(제63조).","c":"상","v":1},"세무사2024_61-47-4":{"f":"총회소집권자가 총회소집을 철회하는 경우, 반드시 총회소집 통지와 동일한 방식으로 통지하여야 하는 것은 아니다.","w":"소집 철회는 소집 통지와 같은 방식을 요구하지 않고 사원들이 알 수 있도록 상당한 방법으로 하면 된다는 것이 판례다.","c":"상","v":1},"세무사2024_61-52-4":{"f":"A와 丙 간에 계약이 적법하게 체결된 경우, 甲이 丙에게 소멸시효 중단사유로서 한 채무의 승인은 특별한 사정이 없는 한 총유물의 관리·처분행위에 해당하지 않는다.","w":"채무의 승인은 총유물을 관리하거나 처분하는 행위가 아니어서 사원총회의 결의가 필요하지 않다는 것이 판례다.","c":"상","v":1},"세무사2025_62-43-5":{"f":"대표자의 행위가 그 직무권한 내에서 적법하게 행하여진 것이 아니라는 것을 피해자 자신이 알았던 경우에는 법인에 손해배상책임을 물을 수 없다.","w":"피해자가 직무 아님을 알았거나 중대한 과실로 몰랐다면 법인의 책임이 인정되지 않는다.","c":"상","v":1},"세무사2025_62-47-3":{"f":"자(子)의 복리를 위하여 자의 성과 본을 모(母)를 따라 변경한 경우에는 자는 모(母)가 속한 종중의 구성원이 된다.","w":"종중 구성원은 공동선조와 성과 본을 같이 하는 성년 후손이다. 제781조 제6항에 따라 성과 본을 모의 것으로 바꾼 성년 자녀는 모가 속한 종중의 구성원이 된다(대법원 2022. 5. 26. 선고 2017다260940).","c":"중","v":1},"세무사2025_62-48-2":{"f":"회의의 목적사항이 기재된 총회의 소집통지는 정관에 특별한 규정이 없으면 개최 1주 전에 발송하여야 한다.","w":"총회 소집은 1주간 전에 통지를 발송하면 된다(제71조). 사원에게 도달해야 하는 것은 아니다.","c":"중","v":1},"세무사2025_62-49-2":{"f":"채권신고기간 동안 채권자에게 변제하지 않더라도 법인은 지연손해배상의무를 부담한다.","w":"채권신고기간 중에 변제하지 못한다고 해도 지연손해배상의무는 면하지 못한다(제90조).","c":"상","v":1},"세무사2025_62-50-1":{"f":"법인의 해산사유는 사단법인과 재단법인 모두 정관의 임의적 기재사항이다.","w":"해산사유는 정한 경우에만 정관에 적는 사항이다(제40조, 제43조).","c":"상","v":1},"세무사2025_62-50-2":{"f":"청산법인이 한 청산의 목적과 관계없는 행위는 효력이 없다.","w":"청산법인은 청산 목적의 범위에서만 권리능력이 있어 그 범위를 벗어난 행위는 무효다.","c":"상","v":1},"세무사2025_62-50-4":{"f":"청산인은 파산의 경우를 제외하고는 해산의 사유 등을 주무관청에 신고하여야 한다.","w":"청산인은 취임 후 3주 내에 해산 사유와 연월일, 청산인의 성명 등을 주무관청에 신고한다(제86조). 관할법원에 하는 것이 아니다.","c":"상","v":1},"세무사2025_62-50-5":{"f":"법인에 대한 청산종결의 등기가 이루어졌더라도 청산사무가 종결되지 않았다면 법인은 소멸하지 않는다.","w":"청산법인은 등기 여부가 아니라 청산사무가 실제로 끝난 때 소멸하고, 그 범위에서는 계속 존속한다.","c":"상","v":1},"세무사2026_63-48-2":{"f":"사원자격의 득실에 관한 사항은 설립등기시 필수적 등기사항이 아니다.","w":"사원 자격의 득실에 관한 규정은 정관 기재사항이지만 설립등기사항(제49조 제2항)에는 포함되지 않는다.","c":"상","v":1},"세무사2026_63-49-4":{"f":"비법인사단의 대표자의 행위가 외관상, 객관적으로 직무에 관한 행위가 아니라면 법인의 불법행위책임이 성립하지 않는다.","w":"제35조 책임은 대표자의 행위가 외관상 직무행위로 보일 때 성립한다.","c":"상","v":1},"세무사2026_63-50-1":{"f":"이사가 여러 명인 경우, 정관에 다른 규정이 없으면 법인의 사무에 관하여 이사 각자가 법인을 대표한다.","w":"대표는 각자 하고(제59조), 이사 과반수로 정하는 것은 사무집행의 의사결정이다(제58조 제2항).","c":"상","v":1},"세무사2026_63-51-2":{"f":"乙로부터 대표이사로서의 모든 권한을 포괄적으로 위임받은 丙이 甲을 대표하여 한 대행행위의 효력은 원칙적으로 甲에게 미치지 않는다.","w":"대표자는 대표 업무를 포괄적으로 다른 사람에게 맡길 수 없고, 그런 위임에 따른 대행행위는 법인에 효력이 없다.","c":"상","v":1},"세무사2026_63-51-3":{"f":"甲의 정관에 乙의 대표권을 제한하는 규정이 있더라도 이를 등기하지 않은 경우, 甲은 대표권 제한사실로써 악의의 제3자에게 대항할 수 없다.","w":"대표권 제한은 정관 기재와 등기가 모두 있어야 제3자에게 대항할 수 있다(제60조). 판례상 제3자의 선의ㆍ악의는 불문한다.","c":"상","v":1},"세무사2026_63-51-5":{"f":"乙의 고의적 불법행위로 인한 甲의 민법 제35조에 따른 손해배상책임에는 피해자에게 과실이 있으면 과실상계의 법리를 적용할 수 있다.","w":"법인의 불법행위책임에도 피해자의 과실을 참작하는 과실상계가 적용된다.","c":"상","v":1},"세무사2016_53-71-1":{"f":"甲이 丙의 동의 없이 단독으로 매매계약을 취소한 경우, 그 취소는 다시 취소할 수 없다.","w":"제한능력자도 단독으로 취소할 수 있고(제140조), 취소는 일단 효력이 생기면 다시 취소할 수 없다.","c":"중","v":1},"세무사2016_53-71-3":{"f":"위 매매계약이 甲의 미성년임을 이유로 취소된 경우, 甲은 乙로부터 받은 매매대금을 현존이익의 한도에서 반환하면 된다.","w":"제한능력자는 취소로 인한 반환 범위가 현존이익으로 제한되어 이자나 손해배상 책임이 없다(제141조 단서).","c":"상","v":1},"세무사2016_53-71-4":{"f":"甲은 미성년자인 상태에서는 丙의 동의 없이 단독으로 乙과의 매매계약을 추인할 수 없다.","w":"제한능력자 본인의 추인은 취소 원인이 소멸한 후에 해야 효력이 있다. 미성년자 상태에서는 법정대리인이 추인한다(제144조).","c":"상","v":1},"세무사2016_53-71-5":{"f":"丙이 위 매매계약이 취소할 수 있는 행위라는 사실을 알지 못하고 추인한 경우에는 그 추인은 효력이 없다.","w":"추인은 취소할 수 있는 행위임을 알고서 해야 효력이 있다.","c":"상","v":1},"세무사2016_53-74-4":{"f":"국토의 계획 및 이용에 관한 법률상 토지거래 허가구역 내의 토지에 관하여 허가를 배제하거나 잠탈하는 내용의 매매계약이 체결된 경우, 그 계약은 확정적 무효이다.","w":"처음부터 허가를 배제하거나 잠탈하려는 계약은 허가를 받아도 유효가 될 수 없는 확정적 무효이다. 유동적 무효는 허가를 받을 것을 전제로 한 계약이다.","c":"상","v":1},"세무사2017_54-76-4":{"f":"법률행위가 가분적이거나 그 목적물의 일부가 특정될 수 있다면 일부만을 취소하는 것도 허용된다.","w":"가분적인 법률행위나 일부가 특정되는 경우에는 일부취소가 가능하다는 것이 판례다.","c":"상","v":1},"세무사2017_54-77-2":{"f":"2015년 3월경 甲이 乙에 대한 매매대금 지급청구권을 제3자에게 양도한 경우에는 취소권자인 乙의 행위가 아니므로 법정추인이 되지 않고, 乙은 매매계약을 취소할 수 있다.","w":"법정추인은 취소권자가 이행의 청구, 양도 등을 한 경우에 성립한다(제145조). 상대방 甲이 한 양도는 법정추인 사유가 되지 않는다.","c":"중","v":1},"세무사2017_54-77-3":{"f":"","w":"제한능력자가 아직 능력자가 되지 않았다면 최고는 법정대리인에게 해야 하고(제15조 제2항), 제한능력자 본인에게 한 최고는 효력이 없다. 2014년 6월에 미성년자였던 乙 본인이 확답을 발송하지 않았어도 추인한 것으로 보지 않으므로 乙은 취소할 수 있다.","c":"중","v":1},"세무사2017_54-77-5":{"f":"매매계약 체결시에 乙이 주민등록증을 위조하여 성년자인 것처럼 속임수를 쓰고 이에 甲이 속아서 매매계약을 체결하였다면 乙은 그 매매계약을 취소할 수 없다.","w":"제한능력자가 속임수로 능력자로 믿게 한 때에는 취소권을 잃는다(제17조 제1항).","c":"상","v":1},"세무사2017_54-78-5":{"f":"묵시적 추인도 허용된다.","w":"추인은 방식에 제한이 없어 묵시적으로도 할 수 있다.","c":"상","v":1},"세무사2021_58-72-3":{"f":"무효인 법률행위를 당사자가 그 무효임을 알고 추인한 경우에는 그 무효원인이 소멸된 후에 한하여 새로운 법률행위로 본다.","w":"무효행위 추인은 무효의 원인이 해소된 뒤에 해야 새로운 법률행위로서 효력이 있다.","c":"중","v":1},"세무사2021_58-74-3":{"f":"취소할 수 있는 법률행위가 일단 취소되면, 무효인 법률행위의 추인의 요건과 효력으로서 추인할 수 있다.","w":"취소된 행위는 처음부터 무효가 되므로 무효행위 추인의 요건을 갖추면 추인할 수 있다(제139조).","c":"중","v":1},"세무사2022_59-74-5":{"f":"법정추인이 되기 위해서는 취소권자가 자신에게 취소권이 있음을 알 필요가 없다.","w":"법정추인은 취소권의 존재를 알았는지와 무관하게 제145조의 사유가 있으면 인정된다는 것이 판례다.","c":"상","v":1},"세무사2022_59-76-1":{"f":"매수인은 토지거래허가를 받기 전에는 매도인에게 허가조건부 소유권이전등기를 청구할 수 없다.","w":"허가 전에는 채권적 효력도 없는 유동적 무효 상태여서 이전등기를 청구할 수 없다.","c":"상","v":1},"세무사2022_59-76-2":{"f":"매도인이 허가신청절차 협력의무를 위반한 경우에도, 매수인은 이를 이유로 매매계약을 해제할 수 없다.","w":"허가 전에는 계약이 유동적 무효이므로 이행을 전제로 한 해제를 할 수 없다. 협력의무는 소로 구할 수 있을 뿐이다.","c":"상","v":1},"세무사2022_59-76-3":{"f":"매도인의 허가신청절차 협력의무와 허가 후 매수인의 대금지급의무는 동시이행관계에 있지 않다.","w":"협력의무는 허가를 받기 위한 절차상 의무이고 대금지급의무와 대가관계에 있지 않다.","c":"상","v":1},"세무사2022_59-76-5":{"f":"매도인은 토지거래허가를 받기 전에도 수령한 계약금의 배액을 상환하고 계약을 해제할 수 있다.","w":"유동적 무효인 상태에서도 계약금의 배액을 상환하고 해제할 수 있다는 것이 판례다(제565조).","c":"상","v":1},"세무사2023_60-70-2":{"f":"불공정한 법률행위에 해당하여 무효인 경우에도 무효행위의 전환에 관한 규정이 적용될 수 있다.","w":"불공정한 법률행위에도 제138조의 무효행위 전환 요건이 갖추어지면 적용된다.","c":"상","v":1},"세무사2023_60-71-1":{"f":"무효인 법률행위도 취소의 대상이 될 수 있다.","w":"무효인 법률행위에 취소 원인이 있으면 취소할 수도 있다(이중효).","c":"상","v":1},"세무사2023_60-80-4":{"f":"관할청의 허가를 받기 전까지 乙은 유동적 무효를 이유로 甲에게 지급한 계약금을 부당이득으로 반환청구할 수 없다.","w":"유동적 무효 상태에서는 확정적으로 무효가 될 때까지 부당이득 반환을 청구하지 못한다.","c":"상","v":1},"세무사2024_61-71-1":{"f":"법률행위의 당사자인 미성년자는 그 행위를 취소할 수 있다.","w":"제한능력자 본인도 단독으로 취소할 수 있다(제140조).","c":"상","v":1},"세무사2024_61-71-2":{"f":"상대방이 대리인을 기망하여 계약을 체결한 경우, 본인은 기망을 이유로 그 계약을 취소할 수 있다.","w":"사기 여부는 대리인을 기준으로 판단하고 취소권은 본인에게 귀속한다.","c":"상","v":1},"세무사2024_61-71-3":{"f":"표의자의 중과실로 법률행위의 중요부분에 착오가 있었더라도, 상대방이 그 착오를 알고 이용하였다면 표의자는 취소할 수 있다.","w":"상대방이 착오를 알고 이용한 경우에는 표의자에게 중과실이 있어도 취소할 수 있다.","c":"상","v":1},"세무사2024_61-71-4":{"f":"취소할 수 있는 법률행위는 추인 후에는 취소할 수 없다.","w":"추인한 뒤에는 취소권을 잃는다(제143조 제1항).","c":"상","v":1},"세무사2024_61-73-1":{"f":"허가를 받으면 계약을 맺은 때로 소급하여 매매의 효력이 발생한다.","w":"허가를 받으면 유동적 무효였던 계약이 소급하여 처음부터 유효가 된다.","c":"상","v":1},"세무사2024_61-73-3":{"f":"허가를 받지 않은 상태에서, 乙은 甲을 상대로 부당이득을 이유로 계약금의 반환을 구할 수 없다.","w":"허가 전의 유동적 무효 상태에서는 계약이 확정적으로 무효가 되기 전까지 반환청구가 안 된다.","c":"상","v":1},"세무사2024_61-73-4":{"f":"甲은 매매에 관한 허가가 나오기 전에도 계약금의 배액을 지급하고 계약을 해제할 수 있다.","w":"판례는 허가 전 유동적 무효 상태에서도 계약금 배액 상환에 의한 해제를 인정한다.","c":"상","v":1},"세무사2024_61-73-5":{"f":"매매계약을 체결할 당시 ‘甲이 허가를 받기 위한 협력 자체를 이행하지 아니하면 乙에게 일정한 손해액을 배상한다’는 약정을 하였고 甲이 협력을 거부한 경우, 乙은 甲에게 그 약정에 따른 손해배상을 청구할 수 있다.","w":"협력의무 불이행에 대한 손해배상액 약정은 유효해서 이를 근거로 청구할 수 있다는 것이 판례다.","c":"중","v":1},"세무사2025_62-77-4":{"f":"제한능력을 이유로 취소할 수 있는 법률행위에 대한 법정대리인의 추인은 그 취소의 원인이 소멸되기 전에도 효력이 있다.","w":"취소 원인이 소멸한 후라는 요건은 제한능력자 본인의 추인에만 적용된다. 법정대리인은 언제든 추인할 수 있다.","c":"상","v":1},"세무사2025_62-79-5":{"f":"매매계약이 약정된 매매대금의 과다로 말미암아 민법 제104조에서 정하는 ‘불공정한 법률행위’에 해당하여 무효인 경우에도 무효행위의 전환에 관한 민법 제138조가 적용될 수 있다.","w":"불공정한 법률행위로 무효인 경우에도 제138조의 전환이 적용될 수 있다는 것이 판례다.","c":"상","v":1},"세무사2026_63-71-2":{"f":"관할관청의 허가가 있으면 그 계약은 소급하여 확정적으로 유효하게 된다.","w":"허가를 받으면 유동적 무효였던 계약이 계약 체결 때부터 유효한 것으로 확정된다.","c":"상","v":1},"세무사2026_63-71-3":{"f":"X토지에 관한 토지거래허가구역의 지정이 해제되더라도 특별한 사정이 없는 한, 관할 관청의 허가 없이도 위 매매계약은 유효하게 된다.","w":"허가구역 지정이 해제되면 허가를 받을 필요가 없어져 유동적 무효였던 계약이 확정적으로 유효하다.","c":"상","v":1},"세무사2026_63-71-4":{"f":"乙이 관할관청의 허가를 얻기 전에 지급하기로 한 대금을 지급하지 않더라도 甲은 이를 이유로 위 매매계약을 해제할 수 없다.","w":"허가 전에는 대금 지급의무가 아직 이행 단계에 이르지 않아 채무불이행을 이유로 해제할 수 없다.","c":"상","v":1},"세무사2026_63-71-5":{"f":"甲이 허가신청절차 협력의무를 위반한 경우에도, 乙은 이를 이유로 위 매매계약을 해제할 수 없다.","w":"허가 전의 유동적 무효 상태에서는 협력의무 위반을 이유로 해제할 수 없고, 협력의무의 이행을 소로 구할 수 있을 뿐이다.","c":"상","v":1},"세무사2026_63-72-2":{"f":"무효인 가등기를 유효한 등기로 전용하기로 약정하였다면, 그 약정한 때부터 유효한 등기로 되고 소급하여 유효해지지는 않는다.","w":"무효 등기의 유용은 약정한 때부터 효력이 있고, 그 사이에 이해관계를 맺은 제3자에게 소급하여 대항할 수 없다.","c":"중","v":1},"세무사2026_63-72-3":{"f":"무권리자의 처분행위에 대하여 권리자가 추인하면 특별한 사정이 없는 한, 그 처분행위가 소급하여 유효한 행위로 된다.","w":"권리자가 추인하면 무권리자의 처분은 처분 시로 소급하여 유효하다.","c":"상","v":1},"세무사2026_63-72-4":{"f":"법률행위가 취소되어 무효인 경우, 무효행위 추인의 요건을 갖추면 추인할 수 있다.","w":"취소된 행위는 소급하여 무효가 되므로 요건을 갖추면 무효행위 추인으로 다시 효력을 줄 수 있다.","c":"중","v":1},"세무사2026_63-72-5":{"f":"묵시적인 방법으로 이루어진 추인도 특별한 사정이 없는 한, 그 효력이 인정된다.","w":"추인의 의사표시는 방식에 제한이 없어 묵시적으로도 할 수 있다.","c":"상","v":1},"세무사2016_53-73-1":{"f":"표현대리가 성립하더라도 유권대리와 별개의 주장이므로, 유권대리에 관한 주장 속에는 표현대리의 주장이 포함되지 않는다.","w":"유권대리와 표현대리는 요건과 효과가 다른 별개의 법률요건이어서 표현대리는 따로 주장해야 한다.","c":"상","v":1},"세무사2017_54-69-3":{"f":"월권행위는 기본대리권의 내용이 되는 법률행위와 동종 또는 유사한 것일 필요가 없다.","w":"권한을 넘은 표현대리는 기본대리권이 있으면 성립하고, 월권행위가 기본대리권과 같은 종류일 필요는 없다.","c":"중","v":1},"세무사2021_58-66-5":{"f":"타인간의 거래에서 세무회계상 필요로 자신의 납세번호증을 이용하도록 허락한 사실만으로는 그 거래에 관하여 대리권 수여의 표시가 있다고 보지 않는다.","w":"납세번호증의 이용을 허락한 것만으로는 그 거래에 관한 대리권을 수여한다는 표시로 볼 수 없다.","c":"상","v":1},"세무사2022_59-67-1":{"f":"법정대리권도 기본대리권에 포함된다.","w":"판례는 법정대리권도 기본대리권이 될 수 있다고 본다.","c":"상","v":1},"세무사2022_59-73-5":{"f":"표현대리가 성립하는 경우에는 본인은 과실상계의 법리를 유추적용하여 자신의 책임을 경감할 수 없다.","w":"표현대리가 성립하면 본인은 계약상 책임을 지며 상대방의 과실을 이유로 책임을 줄일 수 없다.","c":"상","v":1},"세무사2023_60-68-1":{"f":"대리인이 대리권 소멸 후 그의 기존 대리권 범위를 벗어나는 대리행위를 한 경우에도 표현대리가 성립할 여지가 있다.","w":"제129조와 제126조가 중첩해서 성립할 수 있다는 것이 판례다.","c":"상","v":1},"세무사2023_60-68-2":{"f":"채권자에게 주채무자를 위해 보증을 서줄 의사가 있음을 밝힌 것만으로는 특별한 사정이 없는 한 해당 보증계약에 관해 주채무자에게 대리권을 수여함을 표시한 것으로 볼 수 없다.","w":"보증을 설 의사를 밝힌 것과 대리권을 수여했다고 표시한 것은 다르다.","c":"중","v":1},"세무사2023_60-68-4":{"f":"무권대리행위의 추인이 무권대리인에 대하여 행해진 경우 상대방이 추인 사실을 알지 못한 때에는 철회권을 상실하지 않는다.","w":"무권대리인에게 한 추인은 상대방이 추인 사실을 안 때에 비로소 상대방에게 대항할 수 있다(제132조).","c":"상","v":1},"세무사2023_60-68-5":{"f":"무권대리인이 본인을 단독상속한 경우 무권대리인은 상대방이 선의ㆍ무과실인 때에 한하여 추인을 거절하지 못한다.","w":"판례는 무권대리인이 본인을 단독상속한 뒤 무효를 주장하는 것을 신의칙에 반한다고 본다. 상대방의 선의·악의로 결론을 가른 판례는 찾지 못했고, 제135조 책임이 선의·무과실 상대방에게만 생긴다는 데서 X로 본 것으로 보인다.","c":"하","v":1},"세무사2024_61-69-1":{"f":"대리인이 임의로 선임한 복대리인의 권한도 기본대리권이 될 수 있다.","w":"판례는 복대리인의 권한을 기본대리권으로 인정한다.","c":"상","v":1},"세무사2024_61-69-3":{"f":"법정대리권을 기본대리권으로 하여서도 권한을 넘은 표현대리가 성립할 수 있다.","w":"법정대리권도 기본대리권이 될 수 있다.","c":"상","v":1},"세무사2024_61-69-4":{"f":"정당한 이유의 유무는 대리행위 당시의 사정을 고려하여 판정한다.","w":"표현대리의 정당한 이유는 대리행위가 이루어진 때를 기준으로 판단하며 변론종결 시가 아니다.","c":"상","v":1},"세무사2024_61-69-5":{"f":"표현대리가 성립하는 경우, 상대방에게 과실이 있더라도 과실상계의 법리를 유추 적용할 수 없다.","w":"표현대리가 성립하면 본인이 책임을 지고, 상대방의 과실로 책임을 줄일 수 없다.","c":"상","v":1},"세무사2024_61-70-2":{"f":"甲의 추인은 무권대리행위가 있음을 알고 그 행위의 효과를 자기에게 귀속시키도록 하는 단독행위의 성질을 갖는다.","w":"무권대리의 추인은 본인이 하는 상대방 있는 단독행위이지 계약이 아니다.","c":"상","v":1},"세무사2024_61-70-4":{"f":"丙이 정한 최고 기간 내에 甲이 확답을 발하지 않으면 추인을 거절한 것으로 본다.","w":"본인이 최고 기간 내에 확답하지 않으면 추인을 거절한 것으로 본다(제131조).","c":"상","v":1},"세무사2024_61-70-5":{"f":"甲의 사망으로 乙이 X를 단독 상속한 경우, 乙이 무권대리를 이유로 계약의 무효를 주장하는 것은 신의칙에 반한다.","w":"무권대리인이 본인을 상속하고 나서 무권대리를 이유로 무효를 주장하는 것은 신의칙에 반하므로 허용되지 않는다.","c":"상","v":1},"세무사2025_62-75-2":{"f":"강행법규에 위반되어 무효인 대리행위에는 표현대리의 법리가 적용되지 않는다.","w":"표현대리는 대리권의 흠을 메우는 제도라서 행위 자체가 강행법규 위반으로 무효이면 적용되지 않는다.","c":"상","v":1},"세무사2025_62-78-1":{"f":"상대방이 유효한 철회를 한 후에는 본인은 무권대리행위를 추인할 수 없다.","w":"철회가 있으면 계약이 확정적으로 효력이 없게 되어 본인이 더 추인할 수 없다.","c":"상","v":1},"세무사2026_63-67-1":{"f":"법정대리권을 기본대리권으로 하는 표현대리도 성립할 수 있다.","w":"법정대리권도 기본대리권이 될 수 있다.","c":"상","v":1},"세무사2026_63-67-2":{"f":"사실혼 부부의 일상가사대리권을 기본대리권으로 하는 표현대리도 성립할 수 있다.","w":"일상가사대리권도 기본대리권이 될 수 있다.","c":"상","v":1},"세무사2026_63-67-4":{"f":"복임권 없는 대리인이 선임한 복대리인의 권한을 기본대리권으로 하는 표현대리도 성립할 수 있다.","w":"복임권 없는 대리인이 선임한 복대리인의 권한도 기본대리권이 될 수 있다는 것이 판례다.","c":"중","v":1},"세무사2026_63-67-5":{"f":"상대방이 대리인에게 대리권이 있다고 믿을만한 정당한 사유가 있는지의 여부는 대리행위 당시를 기준으로 판단하여야 한다.","w":"정당한 사유는 대리행위 당시의 사정으로 판단하며 변론종결 시를 기준으로 하지 않는다.","c":"상","v":1},"세무사2026_63-69-5":{"f":"乙의 무권대리행위가 제3자의 위법행위에 의해 야기된 경우에도 乙의 丙에 대한 손해 배상책임이 부정되지 않는다.","w":"무권대리인의 제135조 책임은 무과실책임이다. 무권대리행위가 제3자의 기망이나 문서위조 같은 위법행위로 일어났어도 책임은 부정되지 않는다(대법원 2014. 2. 27. 선고 2013다213038).","c":"상","v":1},"세무사2021_58-54-1":{"f":"다가오는 2월 16일부터 5일간이라고 한 경우에 기산점은 2월 16일이 된다.","w":"장래의 특정한 날부터 시작하는 기간은 그날 오전 영시부터 시작하므로 첫날을 산입한다(제157조 단서). 기산점은 2월 16일이다.","c":"상","v":1},"세무사2021_58-54-2":{"f":"원칙적으로 정년이 60세라 함은 만60세에 도달하는 날을 의미한다.","w":"판례는 정년 60세를 만 60세가 되는 날로 본다. 만 61세가 되는 날의 전날까지라는 뜻이 아니다.","c":"상","v":1},"세무사2021_58-54-4":{"f":"5월 16일 정오에 오늘부터 6일간이라고 한 경우에 5월 17일이 공휴일이어도, 그 기산점은 5월 17일이 된다.","w":"오전 영시가 아닌 때 시작하는 기간은 초일을 산입하지 않아 다음 날이 기산점이고, 기산점이 공휴일인지는 영향이 없다.","c":"상","v":1},"세무사2021_58-54-5":{"f":"기간의 말일이 토요일인 경우에는 그 다음 월요일에 기간이 만료된다.","w":"말일이 토요일 또는 공휴일이면 기간은 그 익일로 만료한다(제161조). 익일인 일요일도 공휴일이므로 기간은 월요일에 만료한다.","c":"중","v":1},"세무사2023_60-75-1":{"f":"기간을 주, 월 또는 연으로 정한 때에는 역에 의하여 계산한다.","w":"주, 월, 연 단위 기간은 일로 환산하지 않고 역법에 따라 계산한다(제160조).","c":"상","v":1},"세무사2025_62-68-2":{"f":"","w":"제161조는 기간의 말일이 토요일 또는 공휴일이면 그 익일로 만료한다고 정하고 있어(2007. 12. 21. 개정) 원문은 조문과 같다. 공식 정답 X의 근거를 찾지 못했다(정답 오류 또는 원문 옮김 오류 의심).","c":"하","v":1},"세무사2026_63-75-3":{"f":"초일불산입의 원칙에 관한 민법 제157조는 임의규정이므로 당사자의 합의로 달리 정할 수 있다.","w":"제157조는 당사자의 특약이나 법령으로 달리 정할 수 있는 임의규정이다.","c":"상","v":1},"세무사2016_53-78-1":{"f":"상인이 판매한 상품의 대가로 발생된 채권은 3년의 소멸시효에 걸린다.","w":"상인이 판매한 상품의 대가는 민법 제163조 제6호에 따라 3년의 단기소멸시효에 걸린다. 상법의 5년보다 짧은 민법의 단기시효가 우선한다.","c":"상","v":1},"세무사2016_53-79-4":{"f":"채무자가 권리의 존재를 알지 못한 상태에서 시효가 진행되기 전에 승인한 것은 시효중단의 효력이 없다.","w":"시효중단 사유인 승인은 소멸시효가 진행을 시작한 뒤에만 할 수 있고, 그 전에 한 승인으로는 시효가 중단되지 않는다는 것이 판례다.","c":"상","v":1},"세무사2016_53-80-5":{"f":"소멸시효의 실제 기산일과 당사자가 주장하는 기산일이 서로 다른 경우, 법원은 당사자가 주장하는 기산일을 기준으로 시효기간을 계산하여야 한다.","w":"기산일은 변론주의의 적용을 받아 법원이 당사자가 주장한 기산일과 다른 날을 기준으로 삼을 수 없다.","c":"상","v":1},"세무사2017_54-70-2":{"f":"1년 이내의 기간으로 정한 이자의 소멸시효기간은 3년이다.","w":"1년 이내의 기간으로 정한 이자 채권은 3년의 단기소멸시효에 걸린다(제163조 제1호). 이자에 1년 시효는 없다.","c":"상","v":1},"세무사2017_54-72-5":{"f":"공유물분할청구권은 소유권과 독립하여 소멸시효에 걸리지 않는다.","w":"공유물분할청구권은 공유관계에서 나오는 형성권으로서 소유권과 독립한 소멸시효의 대상이 아니다.","c":"상","v":1},"세무사2017_54-74-1":{"f":"소유권은 소멸시효에 걸리지 않는다.","w":"소유권은 소멸시효의 대상이 아니라 다른 사람이 취득시효로 취득하는 방식으로 잃을 수 있을 뿐이다(제162조 제2항).","c":"상","v":1},"세무사2021_58-57-1":{"f":"가압류의 피보전채권에 관하여 승소판결이 확정되더라도 가압류의 집행보전 효력이 존속하는 동안은 가압류에 의한 시효중단의 효력도 계속된다.","w":"가압류에 의한 시효중단은 가압류 집행보전의 효력이 계속되는 동안 지속된다는 것이 판례다.","c":"상","v":1},"세무사2021_58-58-4":{"f":"주택임대차 종료 후 임차인이 보증금을 반환받기 위해 임차목적물을 적법하게 점유하고 있는 경우에 보증금반환채권의 시효는 진행하지 않는다.","w":"임차인이 목적물을 점유하며 보증금을 받으려 하는 동안은 권리를 행사하지 않는 상태로 볼 수 없어 소멸시효가 진행하지 않는다는 것이 판례다.","c":"상","v":1},"세무사2021_58-59-1":{"f":"제척기간은 소멸시효와 달리 중단이 인정되지 않는다.","w":"제척기간은 중단 제도가 없고 기간 안에 권리를 행사해야 한다.","c":"상","v":1},"세무사2021_58-59-3":{"f":"제척기간에 따른 권리소멸은 법원의 직권조사사항이다.","w":"제척기간은 당사자가 주장하지 않아도 법원이 직권으로 고려한다.","c":"상","v":1},"세무사2021_58-59-4":{"f":"특별한 사정이 없는 한 제척기간이 규정되어 있는 권리는 재판외에서도 행사할 수 있다.","w":"제척기간 안에 소를 제기해야 하는 권리(출소기간)가 아니면 재판 밖에서 행사해도 된다.","c":"중","v":1},"세무사2021_58-59-5":{"f":"제척기간이 규정되어 있는 권리는 제척기간이 경과하면 당사자의 원용이 없어도 소멸한다.","w":"제척기간은 기간 경과로 당연히 권리가 소멸한다. 원용이 필요한 것은 소멸시효다.","c":"상","v":1},"세무사2022_59-77-5":{"f":"매매예약완결권의 행사기간을 30년으로 약정한 경우에는 그 약정한 기간 내에 예약완결권을 행사할 수 있다.","w":"예약완결권의 행사기간을 약정한 때에는 그 기간이 적용된다. 약정이 없을 때 예약 성립일부터 10년이다.","c":"상","v":1},"세무사2022_59-78-3":{"f":"부당이득반환청구권은 권리가 발생한 때로부터 소멸시효가 진행한다.","w":"기한의 정함이 없는 채권은 성립한 때부터 진행하며 채권자가 이행을 청구한 때부터가 아니다(제166조 제1항).","c":"상","v":1},"세무사2022_59-79-3":{"f":"시효중단의 효력 있는 승인에는 상대방의 권리에 관한 처분의 능력이나 권한 있음을 요하지 않는다.","w":"승인은 관념의 통지여서 처분능력이나 처분권한이 필요하지 않다(제177조).","c":"상","v":1},"세무사2023_60-76-4":{"f":"제척기간은 특별한 사유가 없는 한 권리가 발생한 때로부터 기산한다.","w":"제척기간은 권리를 행사할 수 있는 때가 아니라 권리가 발생한 때부터 진행한다.","c":"상","v":1},"세무사2023_60-79-5":{"f":"채권양수인이 채권양도의 대항요건을 갖추지 못한 상태에서 채무자를 상대로 재판상 청구를 한 경우에도 소멸시효 중단사유인 재판상 청구에 해당한다.","w":"대항요건을 갖추지 않았더라도 양수인이 채권자로서 한 재판상 청구는 시효중단 효력이 있다.","c":"상","v":1},"세무사2024_61-77-5":{"f":"채권자가 보증인에 대하여 이행청구를 하더라도 채권자의 주채무자에 대한 채권은 시효가 중단되지 않는다.","w":"시효중단의 효력은 당사자와 승계인 사이에서만 생겨서 보증인에 대한 청구가 주채무자에게 미치지 않는다(제169조).","c":"상","v":1},"세무사2024_61-78-4":{"f":"후순위 저당권자는 선순위 저당권의 피담보채권의 시효소멸을 주장할 수 없다.","w":"후순위 저당권자는 시효소멸로 간접적 이익을 받을 뿐 시효 이익을 직접 받는 사람이 아니라서 원용할 수 없다.","c":"상","v":1},"세무사2024_61-79-4":{"f":"만일 甲과 乙 사이의 매매계약이 적법하게 취소된 경우, 乙의 甲에 대한 매매대금반환청구권은 시효로 소멸할 수 있다.","w":"취소로 생긴 부당이득반환청구권도 소멸시효의 적용을 받는다.","c":"중","v":1},"세무사2024_61-80-5":{"f":"만일 甲과 乙이 합의로 예약완결권 행사의 기산일을 2012. 1. 1.로 정했더라도 그 기산일은 2010. 1. 1.이다.","w":"예약완결권의 제척기간은 권리가 발생한 예약 성립일부터 진행한다. 행사 시기를 따로 약정했어도 그때부터 10년으로 늘어나지 않는다(대법원 1995. 11. 10. 선고 94다22682).","c":"상","v":1},"세무사2025_62-64-5":{"f":"근저당권설정 약정에 의한 근저당권설정등기청구권은 그 피담보채권과는 별도로 소멸시효에 걸린다.","w":"근저당권설정등기청구권은 피담보채권과 독립한 채권적 청구권이라서 따로 소멸시효에 걸린다.","c":"상","v":1},"세무사2025_62-65-5":{"f":"채무 이행을 청구할 수 있는 기간을 그 채무의 소멸시효기간보다 짧게 정하고 그 청구기간이 경과하면 채무가 소멸하도록 하는 약정은 유효하다.","w":"소멸시효는 법정기간보다 단축하거나 경감하는 약정이 허용된다(제184조 제2항).","c":"상","v":1},"세무사2025_62-66-5":{"f":"채무자는 현존하지 아니하는 장래의 채권을 미리 승인할 수 없다.","w":"승인은 이미 존재하는 권리에 대하여 하는 것이므로 장래 발생할 채권에 대한 승인은 시효중단 사유가 아니다.","c":"상","v":1},"세무사2025_62-67-1":{"f":"세무사의 직무에 관한 채권에는 3년의 단기시효기간이 적용되지 않는다.","w":"제163조 제5호의 3년 단기시효는 변호사·변리사·공증인·공인회계사·법무사의 직무에 관한 채권에만 적용된다. 세무사의 직무에 관한 채권은 이 규정이 유추적용되지 않고 상사채권도 아니어서 10년의 소멸시효에 걸린다(대법원 2022. 8. 25. 선고 2021다311111).","c":"상","v":1},"세무사2026_63-76-4":{"f":"채무자가 시효완성 후 채무를 승인한 경우에도 그것만으로 시효이익을 포기한 것으로 간주되지 않는다.","w":"시효이익 포기는 시효완성을 알고 그 이익을 버리겠다는 의사표시가 있어야 인정된다. 시효완성 후 채무를 승인했다는 사정만으로는 간주는 물론 추정도 되지 않는다(대법원 2025. 7. 24. 선고 2023다240299 전원합의체 판결로 종전 추정 법리 폐기).","c":"상","v":1},"세무사2026_63-78-1":{"f":"甲이 丙에 대하여 보증채무의 이행을 청구한 경우에도, 이로써 甲의 乙에 대한 채권은 시효가 중단되지 않는다.","w":"시효중단은 당사자와 승계인 사이에서만 효력이 있으므로 보증인에 대한 청구가 주채무자에게 미치지 않는다(제169조).","c":"상","v":1},"세무사2016_53-46-1":{"f":"2015. 4. 20. 乙이 甲에 대한 실종선고를 청구하면 인용될 수 없다.","w":"항공기 추락에 따른 특별실종은 추락 뒤 1년간 생사가 분명하지 않아야 선고할 수 있다(민법 제27조 제2항). 2014. 10. 20.부터 1년이 지나지 않은 2015. 4. 20.에는 요건을 갖추지 못했다.","c":"상","v":1},"세무사2016_53-46-2":{"f":"乙과 丙이 생존해 있으므로, 甲에 대한 丁의 실종선고 청구는 인용될 수 없다.","w":"실종선고는 이해관계인이나 검사가 청구한다(민법 제27조). 판례는 선순위 상속인이 있으면 후순위 상속인은 이해관계인이 아니라고 본다. 배우자 乙과 직계존속 丙이 상속인이므로 형제자매 丁은 청구할 수 없다.","c":"상","v":1},"세무사2022_59-49-2":{"f":"A법인은 주된 사무소 소재지인 서울에서 설립등기를 하여야 비로소 성립한다.","w":"법인은 주된 사무소 소재지에서 설립등기를 함으로써 성립한다(민법 제33조). 대표자의 주소지는 기준이 아니다.","c":"상","v":1},"세무사2026_63-51-1":{"f":"乙은 주무관청의 허가가 없더라도 사임할 수 있다.","w":"이사의 사임은 법인에 대한 일방적 의사표시로 하고 주무관청의 허가가 필요 없다. 판례는 사임 의사표시가 법인에 도달하면 원칙적으로 효력이 생긴다고 본다.","c":"중","v":1},"세무사2022_59-72-3":{"f":"丙의 대리권은 특별한 사정이 없는 한 乙의 대리권이 소멸하면 함께 소멸한다.","w":"복대리권은 대리인의 대리권에 기초하므로 그 범위를 넘을 수 없고, 대리인의 대리권이 소멸하면 복대리권도 소멸한다.","c":"중","v":1},"세무사2017_54-77-4":{"f":"甲은 乙이 추인을 하기 전이라도 매매계약의 이행을 거절할 수 없다.","w":"제한능력자와 맺은 계약은 취소되기 전까지 유효하다. 상대방 甲에게는 확답을 촉구할 권리(민법 제15조)와 철회권(제16조)이 있을 뿐, 추인 전이라는 이유로 이행을 거절할 권리는 없다.","c":"상","v":1},"세무사2017_54-65-3":{"f":"乙이 미성년자인 경우에는 乙은 노트북에 대한 대금을 지급할 책임을 지지 않는다.","w":"대리인으로서 계약한 사람이 제한능력자이면 상대방에 대한 무권대리인의 이행·손해배상 책임이 생기지 않는다(민법 제135조 제2항).","c":"상","v":1},"세무사2022_59-69-2":{"f":"특별한 사정이 없는 한 매매계약은 계약시에 소급하여 그 효력이 생긴다.","w":"무권대리행위의 추인은 다른 의사표시가 없으면 계약 시로 소급하여 효력이 생긴다(민법 제133조).","c":"상","v":1},"세무사2024_61-70-3":{"f":"甲의 추인이 있으면 계약시에 소급하여 그 효력이 생긴다.","w":"추인은 다른 의사표시가 없으면 계약 시로 소급하여 효력이 생기고, 제3자의 권리는 해하지 못한다(민법 제133조).","c":"상","v":1},"세무사2026_63-79-3":{"f":"丁은 乙의 甲에 대한 채권이 시효로 소멸하였음을 주장할 수 있다.","w":"물상보증인은 피담보채권이 소멸하면 저당권 부담에서 벗어나는 직접 이익을 얻는 사람이므로 피담보채권의 소멸시효를 원용할 수 있다는 것이 판례다.","c":"상","v":1},"세무사2016_53-42":{"w":"계약해제권은 일방적 의사표시로 법률관계를 바꾸는 형성권이다. 항변권은 상대방의 청구를 거절할 수 있는 권리(동시이행의 항변권, 보증인의 최고·검색의 항변권 등)다.\n① 친권은 가족권, ② 손해배상청구권은 청구권, ③ 취소권은 형성권, ④ 사원총회소집청구권은 사원권이다.","c":"상","v":1},"세무사2016_53-59":{"w":"회사합병은 소멸회사의 권리의무가 존속회사로 포괄적으로 이전되므로 포괄승계다.\n① 무주물선점은 원시취득, ③ 상속은 포괄승계, ④ 저당권의 순위승진은 권리의 내용(순위)의 변경, ⑤ 건물 멸실은 권리가 절대적으로 소멸하는 경우다.","c":"상","v":1},"세무사2017_54-41":{"w":"소유권은 양도·상속이 가능해 일신전속권이 아니다. 일신전속권은 친권·부양청구권처럼 특정인에게만 귀속되는 권리다.\n② 저당권은 피담보채권에 부종하는 종된 권리, ③ 임금채권은 청구권, ④ 소유권은 누구에게나 주장할 수 있는 절대권, ⑤ 지상권은 토지를 직접 지배하는 지배권이다.","c":"상","v":1},"세무사2022_59-42":{"w":"계약해제권은 상대방에 대한 일방적 의사표시로 계약관계를 소멸시키는 형성권이다.","c":"상","v":1},"세무사2024_61-41":{"w":"ㄱ O: 입원계약에 따라 병원은 입원환자의 소지품 도난방지에 필요한 조치를 할 신의칙상 보호의무를 진다.\nㄴ X: 토지거래허가 없이 체결한 계약은 확정적으로 무효이므로, 허가가 없음을 이유로 무효를 주장하는 것은 특별한 사정이 없으면 신의칙에 반하지 않는다.\nㄷ O: 강행규정 위반으로 무효인 노사합의라도 신의칙을 우선 적용할 만한 특별한 사정이 있으면 무효 주장이 신의칙에 위배될 수 있다.","c":"중","v":1},"세무사2024_61-55":{"w":"취득시효에 의한 소유권 취득은 종전 소유권에 기초하지 않는 원시취득이다. 승계취득이라는 ②가 옳지 않다.\n① 신축은 원시취득, ③ 상속은 포괄승계, ④ 인도청구권이 손해배상청구권으로 바뀌는 것은 권리 내용의 변경, ⑤ 전소(全燒)로 소유권이 없어지면 절대적 소멸이다.","c":"상","v":1},"세무사2026_63-42":{"w":"ㄱ O: 유효하게 성립한 계약상 급부를 법원이 신의칙을 근거로 감축하는 것은 원칙적으로 허용되지 않는다.\nㄴ O: 시효완성 사실을 모르고 권리주장을 하지 않기로 한 뒤 이에 반하는 시효주장은 특별한 사정이 없으면 신의칙에 반한다.\nㄷ X: 통상의 임대차관계에서 임대인은 임차인의 안전을 배려할 신의칙상 보호의무를 지지 않는다.","c":"중","v":1},"세무사2026_63-80":{"w":"임차인의 필요비상환청구권(제626조 1항)은 청구권이다.\n계약해제권, 취소권, 일방예약완결권(제564조), 지상물매수청구권(제643조)은 일방적 의사표시로 법률관계를 바꾸는 형성권이다.","c":"상","v":1},"세무사2016_53-44":{"w":"제한능력자 상대방의 확답촉구는 능력자가 되기 전에는 법정대리인에게 해야 한다(제15조). 한정후견 중인 甲 본인에게 하는 확답촉구는 효력이 없다.\n② 한정후견인 乙에게는 선의·악의를 불문하고 할 수 있다. ③④ 단독행위의 거절권(제16조 2항)은 선의 상대방이 제한능력자 또는 법정대리인에게 행사한다. ⑤ 선의 상대방은 추인 전에 계약을 철회할 수 있다(제16조 1항).","c":"중","v":1},"세무사2016_53-48":{"w":"부재자 재산관리 제도는 자연인에 대한 것이다. 법인에 대해 부재자 재산관리인을 선임할 수 없으므로 ③이 옳지 않다.\n① 제30조(동시사망 추정), ② 청산종결등기 후에도 청산사무가 남아 있으면 그 범위에서 청산법인으로 존속, ④⑤ 인정사망은 사망의 추정이어서 반증으로 번복된다.","c":"상","v":1},"세무사2017_54-44":{"w":"③ 피성년후견인은 혼인했다는 이유로 능력이 확대되지 않으므로, 성년후견인이 취소할 수 없는 범위를 따로 지정받지 않았다면 취소권을 행사할 수 있다.\n① 영업허락을 받은 미성년자는 그 영업에 관하여 성년자로 본다(제8조). ② 혼인한 미성년자는 성년으로 본다(제826조의2). ④ 특정후견은 행위능력을 제한하지 않는다. ⑤ 동의를 요하지 않는 범위의 한정후견 피한정후견인은 단독으로 유효하게 행위한다.","c":"상","v":1},"세무사2025_62-45":{"w":"태아는 불법행위로 인한 손해배상청구(제762조), 상속(제1000조 제3항), 유증(제1064조)에서는 이미 출생한 것으로 본다. 부의 사망에 따른 위자료 청구(①)도 제762조에 따라 인정된다.\n증여계약의 수증(④)은 이런 개별 규정이 없고 판례도 태아의 수증능력을 인정하지 않는다(대법원 1982. 2. 9. 선고 81다534).","c":"상","v":1},"세무사2017_54-47":{"w":"법원의 부재자재산관리는 부재자가 재산관리인을 선임한 때, 스스로 관리할 수 있게 된 때, 사망하거나 실종선고를 받은 때 종료된다(제22조, 제23조).\n행방불명은 부재자재산관리의 요건에 해당할 뿐 종료사유가 아니다.","c":"상","v":1},"세무사2016_53-50":{"w":"재단법인 정관의 필요적 기재사항(제43조, 제40조 준용)은 목적, 명칭, 사무소 소재지, 자산에 관한 규정, 이사의 임면에 관한 규정이다.\n해산사유는 임의적 기재사항이다.","c":"상","v":1},"세무사2016_53-53":{"w":"① 생전처분으로 출연한 재산은 법인이 성립한 때에 법인에 귀속한다(제48조 1항). 지명채권도 법인 성립 시에 귀속하고, 채무자에게 통지한 때 귀속한다는 것은 틀리다.\n② 법인설립등기 시 귀속. ③ 착오에 따른 출연행위의 취소가 가능하다는 것이 판례다. ④ 출연자 사망 후 상속등기가 되었어도 부동산은 법인 소유다. ⑤ 그러나 상속인이 제3자에게 처분해 등기를 마쳤다면 제3자가 소유권을 취득한다(법인은 등기 없이 제3자에게 대항하지 못함).","c":"중","v":1},"세무사2017_54-50":{"w":"법인은 주된 사무소 소재지에서 설립등기를 함으로써 성립한다(제33조). 허가는 설립등기의 전제이고 법인격은 설립등기 시에 취득한다.","c":"상","v":1},"세무사2017_54-53":{"w":"사단법인과 재단법인의 공통 해산사유(제77조): 존립기간 만료, 법인의 목적 달성 또는 달성 불능, 파산, 설립허가 취소.\nㄴ·ㄷ이 해당한다. ㄱ 총회 결의는 사단법인만의 해산사유(제77조 2항)이고, ㄹ 직무집행정지처분은 해산사유가 아니다.","c":"상","v":1},"세무사2021_58-53":{"w":"⑤ 비법인사단 대표자가 정관상 대표권 제한을 위반해 거래한 경우 거래상대방이 그 제한을 알았거나 과실로 알지 못한 때에만 무효다(판례). 상대방이 선의·무과실이면 거래는 유효하다.\n① 구성원들은 X를 총유한다(제275조). ② 비법인사단 명의로 등기할 수 있다(부동산등기법 제26조). ③ 민사소송에서 당사자능력이 있다(민사소송법 제52조). ④ 대표자의 직무상 불법행위에는 제35조가 유추적용된다.","c":"상","v":1},"세무사2022_59-47":{"w":"민법은 비영리법인의 설립에 주무관청의 허가를 요구한다(제32조). 허가주의다.","c":"상","v":1},"세무사2022_59-50":{"w":"ㄱ O: 재단법인 설립자가 명칭, 사무소 소재지 또는 이사 임면 방법을 정하지 않고 사망하면 이해관계인이나 검사의 청구로 법원이 정한다(제44조).\nㄴ X: 생전처분으로 출연한 재산은 법인이 성립한 때(설립등기 시) 법인에 귀속한다(제48조 제1항).\nㄷ X: 재단법인 기본재산에 저당권을 설정하는 행위는 정관 기재사항을 바꾸는 것이 아니어서 주무관청의 허가가 필요하지 않다(대법원 2018. 7. 20. 자 2017마1565 결정).","c":"중","v":1},"세무사2024_61-48":{"w":"ㄱ O: 법인과 이사의 이익이 상반되는 사항에 관하여는 이사에게 대표권이 없고 특별대리인을 선임한다(제64조).\nㄴ O: 법인의 채무불이행책임에서 고의·과실은 대표기관인 이사를 기준으로 판단한다.\nㄷ X: 법인이 제35조 제1항 전문에 따라 책임을 지더라도 이사 기타 대표자는 자기의 손해배상책임을 면하지 못한다(제35조 제1항 후문).","c":"상","v":1},"세무사2024_61-49":{"w":"③ 재단법인 성립 후에도 출연자는 착오를 이유로 출연의 의사표시를 취소할 수 있다는 것이 판례다. 취소할 수 없다는 ③이 옳지 않다.\n① 제47조 1항, ② 제47조 2항, ④ 제48조 2항(유언의 효력 발생 시 귀속), ⑤ 제44조.","c":"중","v":1},"세무사2024_61-50":{"w":"ㄱ X: 이사가 여럿이면 각자 법인을 대표한다(제59조 1항).\nㄴ O: 정관 또는 총회 결의로 금지하지 않은 사항에 한해 타인에게 특정 행위를 대리하게 할 수 있다(제62조).\nㄷ X: 이사의 대표권 제한은 정관에 기재해야 효력이 있는 사항(제41조)으로, 정관의 필요적 기재사항은 아니다.\nㄹ O: 대표권 제한은 등기하지 않으면 선의·악의를 불문하고 제3자에게 대항하지 못한다(제60조).","c":"중","v":1},"세무사2024_61-51":{"w":"한국세무사회는 세무사법에 근거한 법정 법인이므로 법인 아닌 사단이 아니다.\n자연부락, 입주자대표회의, 종중, 동·리는 법인 아닌 사단 또는 그에 준하는 단체로 본다.","c":"중","v":1},"세무사2025_62-41":{"w":"사단법인의 설립요건은 비영리 목적, 정관 작성, 주무관청의 허가, 설립등기다. 기본재산의 출연은 재단법인 설립에 필요한 요건이다.","c":"상","v":1},"세무사2026_63-47":{"w":"ㄱ X: 재단법인이 성립한 뒤에도 출연자는 착오 요건을 갖추면 출연행위를 취소할 수 있다.\nㄴ X: 출연재산은 법인이 성립한 때(설립등기 시)에 귀속한다(제48조 1항).\nㄷ X: 출연자가 제3자에게 처분하고 등기까지 마쳤다면 법인은 등기 없이 제3자에게 대항하지 못한다.","c":"중","v":1},"세무사2017_54-55":{"w":"지하수는 토지의 구성부분이어서 독립한 물건이 아니다.\n명인방법을 갖춘 미분리 과실, 입목등기를 마친 수목, 독립 건축물, 권원에 의해 식재한 수목 집단(명인방법)은 토지와 별개의 물건이다.","c":"상","v":1},"세무사2025_62-62":{"w":"권리는 물건이 아니다. 물건은 유체물 및 관리할 수 있는 자연력(제98조)이다.\n② 전기는 동산, ③ 금전은 동산, ④ 신체에서 분리된 머리카락은 동산, ⑤ 입목법상 입목은 토지와 별개의 부동산으로 본다.","c":"상","v":1},"세무사2017_54-58":{"w":"의사능력은 법률행위 일반의 유효요건이다. 특별효력요건은 개별 법률행위에만 요구되는 요건으로, 동의(제5조), 대리권, 기한 도래, 주무관청의 허가가 해당한다.","c":"상","v":1},"세무사2021_58-80":{"w":"ㄱ X: 강박이라는 불법적 방법이 쓰였다는 것만으로는 반사회질서 행위가 되지 않고 강박에 의한 의사표시로 취소 대상일 뿐이다.\nㄴ O: 동기가 표시되거나 상대방에게 알려진 반사회적 동기는 반사회질서 법률행위가 된다.\nㄷ O: 제103조 위반은 절대적 무효여서 선의의 제3자에게도 대항할 수 있다.","c":"중","v":1},"세무사2022_59-60":{"w":"ㄱ O: 대리권 수여는 재산의 출연이 없는 비출연행위다.\nㄴ O: 소유권의 포기는 상대방 없는 단독행위다.\nㄷ O: 의사표시의 존재는 성립요건이고 효과를 주장하는 자가 증명한다.","c":"상","v":1},"세무사2024_61-57":{"w":"사용대차는 대가 없이 빌려 쓰는 무상계약이다. 유상행위의 예가 아니다.\n② 유언은 요식행위, ③ 채권양도는 준물권행위, ④ 매매는 출연행위, ⑤ 유언은 상대방 없는 단독행위다.","c":"상","v":1},"세무사2024_61-58":{"w":"양도소득세를 회피하려는 명의신탁은 그 동기만으로 반사회질서의 법률행위가 되지 않는다(부동산실명법상 별개의 무효 문제).\n① 변호사법 위반 약정, ② 이중매매에 적극 가담, ③ 허위진술 대가 약정, ④ 지자체의 기부금 증여계약은 반사회질서로 무효다.","c":"중","v":1},"세무사2025_62-52":{"w":"근보증계약은 보증인의 보호를 위해 서면 요식을 요하는 요식행위다(제428조의3).\n② 소유권의 포기는 상대방 없는 단독행위, ③ 채무면제는 준물권행위(처분행위), ④ 유언은 사후행위, ⑤ 어음행위는 무인행위다.","c":"중","v":1},"세무사2025_62-53":{"w":"④ 개업공인중개사의 직접거래 금지(공인중개사법 제33조)는 단속규정이어서 위반해도 사법상 효력은 유효하다.\n① 중개수수료 한도 초과 부분 무효, ② 공공임대주택 임차권 전매 제한, ③ 문화재수리업 명의대여, ⑤ 사모투자전문회사 이익보장약정은 효력규정 위반으로 무효다.","c":"중","v":1},"세무사2026_63-55":{"w":"ㄱ O: 유언은 상대방이 없으므로 표의자의 진의를 따르는 자연적 해석이 우선한다.\nㄴ X: 사실인 관습은 강행규정에 반하지 않는 범위에서만 해석 기준이 된다.\nㄷ X: 당사자 쌍방이 일치하여 의도한 물건에 대해 계약이 성립하고, 잘못 기재된 물건에는 성립하지 않는다(오표시무해).","c":"상","v":1},"세무사2026_63-56":{"w":"민사사건의 성공보수약정은 유효하다. 형사사건 성공보수약정만 선량한 풍속에 반해 무효다.\n① 의료법상 비의료인 개설 금지, ② 중개수수료 한도 초과, ③ 변호사법 위반, ⑤ 토지거래허가 잠탈은 강행규정 위반으로 무효다.","c":"중","v":1},"세무사2016_53-64":{"w":"甲과 乙의 허위 매매계약에 관한 설명이다.\nㄱ O: 통정허위표시로 무효(제108조 1항).\nㄴ X: 무효이므로 甲은 소유권에 기한 말소등기를 청구할 수 있다.\nㄷ O: 선의의 제3자 丙에게는 무효를 대항하지 못한다(제108조 2항).\nㄹ O: 선의자가 취득한 권리는 확정적으로 유효해 이후의 악의 전득자 丁도 취득한다.","c":"상","v":1},"세무사2017_54-68":{"w":"대리인이 대리권 범위 밖의 B토지를 산 것은 무권대리의 문제이고 착오로 취소할 사안이 아니다.\n② 표시상의 착오, ③ 표시행위의 성질 착오, ④ 진품 여부에 관한 성질 착오, ⑤ 목적물의 성질 착오는 착오에 의한 의사표시에 해당한다.","c":"상","v":1},"세무사2021_58-71":{"w":"ㄱ O: 발송 후 표의자가 사망해도 의사표시의 효력은 영향을 받지 않는다(제111조 2항).\nㄴ X: 표의자가 과실 없이 상대방을 알 수 없는 경우에 공시송달이 가능하다(제113조).\nㄷ X: 도달주의이므로 상대방이 요지할 수 있는 상태에 이르면 현실 수령이 없어도 효력이 생긴다.","c":"하","v":1},"세무사2022_59-64":{"w":"옳지 않은 것은 ㄴ이다.\nㄱ O: 동거하는 부부 사이에 매매를 원인으로 소유권이전등기를 마친 경우 특별한 사정이 없으면 경험칙상 가장매매로 추정된다는 판례가 있다(대법원 1978. 4. 25. 선고 78다226).\nㄴ X: 가장 소비대차의 차용금채무를 연대보증한 사람이 보증채무를 이행해 구상권을 취득하면 허위표시를 기초로 새로운 법률상 이해관계를 맺은 제3자에 해당한다(제108조 제2항, 판례).\nㄷ O: 중간의 丙이 악의라도 그로부터 전득한 선의의 丁에게는 허위표시의 무효를 대항하지 못한다.","c":"중","v":1},"세무사2024_61-62":{"w":"ㄱ O: 매도인의 해제 후에도 매수인은 착오를 이유로 매매계약을 취소할 수 있다.\nㄴ O: 취소하는 자가 법률행위 내용의 착오와 그 착오가 의사표시에 결정적 영향을 미쳤음을 증명해야 한다.\nㄷ X: 소송행위에는 민법의 착오 규정이 적용되지 않아, 착오로 소를 취하해도 무효로 되지 않고 효력이 유지된다.","c":"하","v":1},"세무사2024_61-63":{"w":"ㄱ O: 강박에 의한 증여의 의사표시는 내심의 효과의사가 있는 것이어서 진의 아닌 의사표시가 아니라 강박에 의한 의사표시(취소 대상)가 된다.\nㄴ X: 진의 아닌 의사표시는 원칙적으로 유효하고, 상대방이 진의 아님을 알았거나 알 수 있었을 때 무효다(제107조 1항).\nㄷ O: 무효는 선의의 제3자에게 대항하지 못한다(제107조 2항).","c":"상","v":1},"세무사2025_62-58":{"w":"ㄱ O: 허위 전세권근저당권부 채권을 압류한 선의의 丁은 제108조 2항의 제3자다.\nㄴ X: 가장매매예약이 철회된 뒤 乙이 서류를 위조해 본등기를 하고 丁이 전득한 사안은 허위표시를 기초로 한 이해관계가 아니어서 제108조의 제3자 문제가 아니다.\nㄷ O: 가장채권의 선의 양수인은 과실이 있어도 보호된다(무과실 불요).","c":"중","v":1},"세무사2026_63-61":{"w":"옳지 않은 것은 ㄴ이다.\nㄱ O: 근저당 설정계약에서 채무자의 동일성에 관한 착오는 중요부분의 착오다.\nㄴ X: 소취하합의는 사법상 계약이어서 민법 제109조에 따라 중요부분의 착오로 취소할 수 있다.\nㄷ O: 중과실 착오라도 상대방이 착오를 알고 이용한 경우에는 취소할 수 있다.","c":"중","v":1},"세무사2026_63-62":{"w":"옳지 않은 것은 ㄱ이다.\nㄱ X: 강박에 의해 당연무효라는 주장 속에 강박을 이유로 취소한다는 주장이 포함되어 있다고 볼 수 없다는 것이 판례다.\nㄴ O: 상대방이 사용자책임을 지는 피용자는 제110조 2항의 제3자에 포함될 수 있다.\nㄷ O: 취소에 따른 부당이득반환청구권과 불법행위 손해배상청구권은 경합하여 선택적으로 행사할 수 있다.","c":"중","v":1},"세무사2016_53-68":{"w":"임의대리권은 본인의 사망, 대리인의 사망·성년후견 개시·파산으로 소멸한다(제127조). 대리인에 대한 한정후견 개시는 소멸사유가 아니다.","c":"상","v":1},"세무사2016_53-75":{"w":"③ 본인이 허락한 자기계약은 유효하다(제124조 단서). 효력이 생기지 않는다는 ③이 옳지 않다.\n① 쌍방대리로 입찰이 무효, ④ 공동대리, ⑤ 등기신청은 채무이행이라 쌍방대리가 허용된다.","c":"상","v":1},"세무사2025_62-80":{"w":"ㄱ O: 본인의 허락이 있으면 쌍방대리가 허용된다(제124조 단서).\nㄴ O: 새 이해관계가 생기지 않는 채무이행은 쌍방대리로도 할 수 있다.\nㄷ O: 제135조 1항의 무권대리인 책임은 무과실책임이다.","c":"상","v":1},"세무사2026_63-68":{"w":"ㄱ X: 매매계약 체결을 위임받은 대리인은 특별한 사정이 없으면 대금을 수령할 권한도 있어, 丙이 乙에게 지급한 변제는 유효하다.\nㄴ X: 계약 체결 대리권에는 해제권이 포함되지 않고, 해제의 의사표시를 수령할 권한도 없다고 본다.\nㄷ X: 유권대리 주장에는 표현대리 주장이 포함되지 않아 법원이 표현대리 성립 여부까지 판단할 의무가 없다.","c":"하","v":1},"세무사2026_63-70":{"w":"복대리인은 대리인이 자기 이름으로 선임하는 본인의 임의대리인이므로 법정대리인이 선임하더라도 법정대리인이 아니다. 법정대리인은 친권자, 후견인, 가정법원이 선임한 재산관리인 등이다.","c":"중","v":1},"세무사2026_63-74":{"w":"상계는 소급효가 있어 단독행위에 조건·기한을 붙일 수 없다(제493조 1항). 도급·매매·위임·고용 계약에는 시기를 붙일 수 있다.","c":"상","v":1},"세무사2017_54-71":{"w":"진의 아닌 의사표시의 무효는 선의의 제3자에게 대항하지 못한다(제107조 2항).\n강행규정 위반, 반사회질서, 불공정한 법률행위, 원시적 불능은 절대적 무효여서 선의의 제3자에게도 대항할 수 있다.","c":"상","v":1},"세무사2023_60-72":{"w":"ㄱ O: 무권리자의 처분행위를 권리자가 추인하면 소급효가 있다.\nㄴ X: 무효행위의 추인은 소급효가 없고 새로운 행위로 본다(제139조).\nㄷ O: 무권대리의 본인 추인은 계약 시로 소급한다(제133조).","c":"상","v":1},"세무사2024_61-72":{"w":"법정추인 사유(제145조): 전부나 일부의 이행, 이행의 청구, 경개, 담보의 제공, 취소할 수 있는 행위로 취득한 권리의 양도, 강제집행.\n이행거절은 사유가 아니다.","c":"상","v":1},"세무사2024_61-74":{"w":"사기로 인한 협의이혼의 취소는 소급효가 인정된다.\n혼인취소·입양취소는 장래에 향해서만 효력이 있고, 근로계약과 조합계약은 이미 이루어진 법률관계를 보호하기 위해 취소의 소급효가 제한된다.","c":"중","v":1},"세무사2025_62-76":{"w":"ㄱ O: 토지거래허가 전 계약은 유동적 무효이고, 허가를 받으면 소급하여 유효해져 새로 계약할 필요가 없다.\nㄴ O: 쌍방이 협력의무 이행 거절 의사를 명백히 표시하면 확정적 무효가 된다.\nㄷ O: 정지조건의 불성취가 확정되면 계약은 확정적으로 무효다.","c":"상","v":1},"세무사2021_58-63":{"w":"⑤ 상대방이 계약 당시 대리권이 없음을 안 때에는 철회할 수 없다(제134조 단서).\n① 철회 후에는 추인할 수 없다. ② 인감증명서 교부만으로는 추인이 아니다. ③ 일부 추인은 상대방 동의가 있어야 유효하다. ④ 승계인도 추인의 상대방이 될 수 있다.","c":"중","v":1},"세무사2021_58-64":{"w":"ㄱ O: 강행법규 위반으로 무효인 행위에는 표현대리가 성립하지 않는다.\nㄴ X: 대리인이 본인 행세를 하며 본인 명의로 한 행위는 대리행위가 아니라 표현대리 문제가 아니다.\nㄷ O: 복임권 없이 선임된 복대리인의 행위에도 기본대리권이 인정되어 권한초과 표현대리가 문제될 수 있다.","c":"하","v":1},"세무사2021_58-65":{"w":"① 상대방은 대리권 없음을 알았더라도 본인에게 추인 여부의 확답을 최고할 수 있다(제131조). 최고할 수 없다는 ①이 옳지 않다.\n② 무권대리인이 제한능력자면 제135조 책임을 지지 않는다(제135조 2항). ③ 상속한 무권대리인의 무효 주장은 신의칙 위반이다. ④ 대금 일부 수령은 추인으로 볼 수 있다. ⑤ 추인은 상대방에게 해야 대항할 수 있다.","c":"중","v":1},"세무사2016_53-77":{"w":"초일을 산입하기로 약정했으므로 기산점은 4월 23일 0시이고, 월 단위 기간은 최후의 월 해당일의 전일 24시에 만료한다(제160조 2항). 6개월 후 10월 22일 24시가 변제 최종 시점이다.","c":"상","v":1},"세무사2017_54-80":{"w":"초일 불산입 원칙에 따라 기산점은 4월 18일 0시다(제157조). 월로 정한 기간은 최후의 월 해당일의 전일 24시에 만료하므로 5월 17일 24시다(제160조 2항).","c":"상","v":1},"세무사2017_54-73":{"w":"원본채권이 시효로 소멸하면 이자채권도 함께 소멸한다(제183조). 이자채권이 소멸하지 않는다는 ⑤가 옳지 않다.\n① 제184조 1항. ② 일부 변제는 채무 승인으로 나머지에도 시효중단 효과가 있다. ③ 시효 완성 후 일부 변제는 채무 전체에 대한 시효이익의 포기로 본다. ④ 포기 시점부터 시효가 새로 진행한다.","c":"중","v":1,"old":1,"ow":"출제 당시 정답 ⑤(③은 옳은 선지). 2025.7.24. 대법원 전원합의체 2023다240299 판결이 「시효완성 후 채무를 승인하면 시효이익을 포기한 것으로 추정한다」는 법리를 폐기하고 일부 변제로 채무 전체의 포기를 추정하던 2013다12464 판결도 변경해, 지금은 ③도 틀린 선지다(시효완성 후 500만 원을 갚았다는 사실만으로는 포기로 보지 않고, 포기 의사가 있었는지를 따로 따진다). ④도 ③을 전제로 하므로 그대로 맞다고 하기 어렵다."},"세무사2021_58-55":{"w":"ㄱ X: 물상보증인이 제기한 채무부존재확인의 소에서 채권자가 응소하는 것은 채무자에 대한 시효중단 사유가 되지 않는다.\nㄴ O: 물상보증인 소유 부동산을 압류하고 채무자에게 통지하면 채무자에 대한 시효중단 효력이 생긴다(제176조).\nㄷ O: 물상보증인은 피담보채권의 소멸시효를 주장할 수 있다.","c":"중","v":1},"세무사2022_59-80":{"w":"소유권에 기한 물권적 청구권, 점유 중인 매수인의 소유권이전등기청구권, 피담보채권이 소멸하지 않은 유치권은 모두 소멸시효에 걸리지 않는다.","c":"상","v":1},"세무사2023_60-78":{"w":"취득시효 완성자가 점유를 상실하면 등기청구권은 점유 상실 시부터 10년의 소멸시효에 걸린다.\n유치권, 소유권에 기한 물권적 청구권, 점유권, 인격권은 소멸시효의 대상이 아니다.","c":"중","v":1},"세무사2024_61-76":{"w":"소유권 침해로 인한 손해배상청구권은 채권이어서 소멸시효에 걸린다.\n점유권은 시효 대상이 아니고, 취소권은 제척기간, 진정명의회복 등기청구권과 공유물분할청구권은 소멸시효 대상이 아니다.","c":"중","v":1},"세무사2026_63-77":{"w":"ㄱ O: 상속회복청구권의 제척기간은 소 제기로 지켜야 한다.\nㄴ X: 점유물반환청구권의 행사기간 1년(제204조 3항)은 출소기간이다.\nㄷ X: 채권양도 통지는 제척기간 준수에 필요한 재판외 행사로 볼 수 없다.\nㄹ O: 예약완결권의 행사기간을 약정했더라도 특별한 사정이 없으면 예약완결권 발생일부터 기산한다.","c":"중","v":1}};
